    gpioSetMode(GPIO_2, PI_OUTPUT);
    gpioSetMode(GPIO_3, PI_OUTPUT);

    // Main loop
    while (!terminate) {
        // Set GPIO 2 to HIGH
        gpioWrite(GPIO_2, 1);
        gpioDelay(1000000); // 1 second

        // Set GPIO 3 to LOW
        gpioWrite(GPIO_3, 0);
        gpioDelay(1000000); // 1 second

        // Report the state of GPIO 2
        printf("GPIO 2: %d\n", gpio_2_state);

        // Report the state of GPIO 3
        printf("GPIO 3: %d\n", gpio_3_state);

        // Sleep for 2 seconds
        sleep(2);
    }

    // Clean up and exit
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return 0;
}

