#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 2
#define VALID_READING_MIN 0
#define VALID_READING_MAX 255

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int gpio_status;
    int reading;

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 2 as an output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    printf("Program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read the digital value from GPIO 2
        reading = gpioRead(GPIO_PIN);

        // Check for errors during GPIO read
        if (reading < 0) {
            fprintf(stderr, "Error reading GPIO %d: %d\n", GPIO_PIN, reading);
            gpioTerminate();
            return 1; // Exit with an error code
        }

        // Validate the reading
        if (reading >= VALID_READING_MIN && reading <= VALID_READING_MAX) {
            // Print the GPIO state
            printf("GPIO %d: %d\n", GPIO_PIN, reading);
        } else {
            fprintf(stderr, "Invalid reading: %d. Reading must be between %d and %d\n", reading, VALID_READING_MIN, VALID_READING_MAX);
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Terminate pigpio library before exiting
    gpioTerminate();

    printf("Program finished.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define REF_VOLTAGE 4.096

int i2c_fd;

int i2c_setup() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }
    return 0;
}

int adsl1115_read_conversion(int fd, int16_t *value) {
    uint8_t config[3];
    uint8_t data[2];
    int result;

    // Configuration register: Single-shot mode, AIN0, +/-4.096V, 128 SPS, Disable comparator
    config[0] = CONFIG_REG;
    config[1] = 0x40 | 0x00 | 0x00 | 0x00 | 0x00 | 0x00 | 0x00 | 0x00; // Single-shot mode, AIN0, +/-4.096V, 128 SPS, Disable comparator
    config[2] = 0x83; // Start single conversion

    result = write(fd, config, 3);
    if (result != 3) {
        perror("Error writing to configuration register");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms)
    usleep(10000); // 10ms

    // Read conversion register (2 bytes)
    result = read(fd, data, 2);
    if (result != 2) {
        perror("Error reading conversion register");
        return -1;
    }

    *value = (data[0] << 8) | data[1];
    *value = *value >> 8; // Remove status bits

    return 0;
}

int main() {
    if (i2c_setup() < 0) {
        return 1;
    }

    while (1) {
        int16_t raw_value;
        float voltage;

        if (adsl1115_read_conversion(i2c_fd, &raw_value) == 0) {
            voltage = (float)raw_value * REF_VOLTAGE / 32768.0;
            printf("Raw: %d, Voltage: %.3f V\n", raw_value, voltage);
        } else {
            fprintf(stderr, "Failed to read ADC value.\n");
        }

        usleep(500000); // 0.5 seconds
    }

    close(i2c_fd);
    return 0;
}

