#define I2C_BUS "/dev/i2c-1"
#define MLX90614_ADDR 0x5A
#define MLX90614_PTAT_REG 0x2400

int main() {
    int file;
    int result;
    uint16_t raw_ptat;
    float temperature;

    // Open I2C bus
    if ((file = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Error opening I2C bus");
        return EXIT_FAILURE;
    }

    // Set slave address
    if (ioctl(file, I2C_SLAVE, MLX90614_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(file);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Read PTAT register
        result = read(file, &raw_ptat, 2);
        if (result != 2) {
            fprintf(stderr, "Error reading PTAT register: %s\n", strerror(errno));
            close(file);
            return EXIT_FAILURE;
        }

        // Convert to temperature (example, adjust as needed)
        temperature = (float)raw_ptat * 0.02 - 273.15; // Example conversion

        // Print temperature
        printf("PTAT: %u, Temperature: %.2f °C\n", raw_ptat, temperature);

        // Wait 5 seconds
        sleep(5);
    }

    // Close I2C bus (this will never be reached in the current loop)
    close(file);

    return EXIT_SUCCESS;
}

