#include <signal.h>
#include <pigpio.h>

#define PWM_GPIO 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int result;
    int pwm_value;

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 18 as PWM output
    result = gpioSetMode(PWM_GPIO, PI_OUTPUT);
    if (result != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output: %d\n", PWM_GPIO, result);
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency
    result = gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);
    if (result != 0) {
        fprintf(stderr, "Failed to set PWM frequency: %d\n", result);
        gpioTerminate();
        return 1;
    }

    // Set PWM range
    result = gpioSetPWMrange(PWM_GPIO, PWM_RANGE);
    if (result != 0) {
        fprintf(stderr, "Failed to set PWM range: %d\n", result);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Generate PWM signal (0 or 1)
        pwm_value = (rand() % 2) + 1; // Simulate a 50% duty cycle
        result = gpioPWM(PWM_GPIO, pwm_value);
        if (result != 0) {
            fprintf(stderr, "Failed to set PWM duty cycle: %d\n", result);
            break; // Exit loop on error
        }

        // Report the PWM state
        printf("PWM state: %d\n", pwm_value);

        // Wait for 0.5 seconds
        gpioDelay(500000); // 0.5 seconds in microseconds
    }

    // Clean up and exit
    gpioPWM(PWM_GPIO, 0); // Stop PWM
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 27

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int read_pulse_width() {
    int start_tick, end_tick, diff;

    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    // Wait for echo to go high (with timeout)
    int timeout = 10000; // 10ms timeout
    while (gpioRead(ECHO_PIN) == 0 && timeout > 0) {
        timeout--;
        gpioDelay(1); // Check every 1 us
    }

    if (timeout == 0) {
        fprintf(stderr, "Error: Echo signal not received (timeout)\n");
        return -1; // Indicate timeout error
    }

    start_tick = gpioTick();

    // Wait for echo to go low (with timeout)
    timeout = 10000; // 10ms timeout
    while (gpioRead(ECHO_PIN) == 1 && timeout > 0) {
        timeout--;
        gpioDelay(1); // Check every 1 us
    }

    if (timeout == 0) {
        fprintf(stderr, "Error: Echo signal not received (timeout)\n");
        return -1; // Indicate timeout error
    }

    end_tick = gpioTick();

    diff = end_tick - start_tick;
    return diff;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    printf("HC-SR04 Distance Measurement\n");

    while (!terminate) {
        int pulse_width = read_pulse_width();

        if (pulse_width > 0) {
            float distance = (pulse_width * 0.0343) / 2;
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Error reading pulse width\n");
        }

        sleep(60);
    }

    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return 0;
}

