#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define CYCLE_COUNT 3
#define DELAY_SECONDS 2

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int gpio_status;
    int gpio_value;

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 18 as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    printf("GPIO 18 set as output. Press Ctrl+C to exit.\n");

    // Main loop
    for (int i = 0; i < CYCLE_COUNT; i++) {
        // Set GPIO high
        gpio_status = gpioWrite(GPIO_PIN, 1);
        if (gpio_status != 0) {
            fprintf(stderr, "Error setting GPIO %d high: %d\n", GPIO_PIN, gpio_status);
            gpioTerminate();
            return 1;
        }
        printf("GPIO %d set high\n", GPIO_PIN);

        // Delay for 2 seconds
        sleep(DELAY_SECONDS);

        // Set GPIO low
        gpio_status = gpioWrite(GPIO_PIN, 0);
        if (gpio_status != 0) {
            fprintf(stderr, "Error setting GPIO %d low: %d\n", GPIO_PIN, gpio_status);
            gpioTerminate();
            return 1;
        }
        printf("GPIO %d set low\n", GPIO_PIN);

        // Delay for 2 seconds
        sleep(DELAY_SECONDS);
    }

    // Terminate pigpio library
    gpioTerminate();

    printf("Program finished.\n");
    return 0;
}

