#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_DELAY_MS 50

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int gpio_status;
    int valid_reading = 0;
    int i;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 17 as an output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    printf("GPIO 17 set as output.  Reading sensor data...\n");

    while (program_running) {
        // Read the sensor value
        gpio_status = gpioRead(GPIO_PIN);

        if (gpio_status == PI_BAD_GPIO) {
            fprintf(stderr, "Error reading GPIO %d\n", GPIO_PIN);
            gpioTerminate();
            return 1;
        }

        // Debounce the reading
        gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Convert ms to microseconds

        // Re-read the sensor value after debounce
        gpio_status = gpioRead(GPIO_PIN);

        if (gpio_status == PI_BAD_GPIO) {
            fprintf(stderr, "Error reading GPIO %d after debounce\n", GPIO_PIN);
            gpioTerminate();
            return 1;
        }

        // Validate the reading
        if (gpio_status == PI_HIGH) {
            valid_reading = 1;
        } else if (gpio_status == PI_LOW) {
            valid_reading = 0;
        } else {
            fprintf(stderr, "Invalid reading: %d\n", gpio_status);
            gpioTerminate();
            return 1;
        }

        // Report the valid reading
        if (valid_reading) {
            printf("Valid reading: %d\n", gpio_status);
        } else {
            printf("Invalid reading, retrying...\n");
        }

        // Small delay to avoid busy-waiting
        gpioDelay(10000); // 10ms
    }

    // Terminate pigpio library before exiting
    gpioTerminate();
    printf("pigpio terminated. Exiting.\n");
    return 0;
}

