#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define SI7021_ADDR 0x40
#define MEASURE_TEMP_CMD 0xE3
#define MEASURE_HUMID_CMD 0xE5

int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("\nCtrl+C pressed. Exiting...\n");
        if (i2c_fd != -1) {
            close(i2c_fd);
        }
        exit(EXIT_SUCCESS);
    }
}

// Function to initialize the I2C bus
int init_i2c(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return fd;
}

// Function to read a single byte from the I2C device
int read_byte(int fd, unsigned char reg) {
    unsigned char buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    if (read(fd, buf, 1) != 1) {
        perror("Error reading from I2C device");
        return -1;
    }
    return buf[0];
}

// Function to write a single byte to the I2C device
int write_byte(int fd, unsigned char reg, unsigned char value) {
    unsigned char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// Function to read temperature from the SI7021
float read_temperature(int fd) {
    if (write_byte(fd, MEASURE_TEMP_CMD, 0) != 0) {
        fprintf(stderr, "Error: Failed to initiate temperature measurement.\n");
        return -1000.0; // Indicate error
    }
    usleep(100000); // Wait for measurement (at least 85ms)
    int raw_temp = read_byte(fd, 0x00);
    if (raw_temp < 0) {
        fprintf(stderr, "Error: Failed to read temperature data.\n");
        return -1000.0; // Indicate error
    }
    float temperature = (175.72 * raw_temp / 65536.0) - 46.85;
    return temperature;
}

// Function to read humidity from the SI7021
float read_humidity(int fd) {
    if (write_byte(fd, MEASURE_HUMID_CMD, 0) != 0) {
        fprintf(stderr, "Error: Failed to initiate humidity measurement.\n");
        return -1000.0; // Indicate error
    }
    usleep(100000); // Wait for measurement (at least 85ms)
    int raw_humidity = read_byte(fd, 0x00);
    if (raw_humidity < 0) {
        fprintf(stderr, "Error: Failed to read humidity data.\n");
        return -1000.0; // Indicate error
    }
    float humidity = (125.0 * raw_humidity / 65536.0) - 6.0;
    return humidity;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C bus
    i2c_fd = init_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Failed to initialize I2C bus.\n");
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        float temperature = read_temperature(i2c_fd);
        float humidity = read_humidity(i2c_fd);

        if (temperature > -999.0 && humidity > -999.0) {
            printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Error: Failed to read temperature or humidity.\n");
        }

        sleep(5);
    }

    // Close I2C bus (this will never be reached in the current loop)
    close(i2c_fd);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PINS {8, 9, 10, 11, 23, 24}
#define NUM_PINS 6
#define CYCLES 256

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int i;
    int pin_states[NUM_PINS];
    int current_state;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    for (i = 0; i < NUM_PINS; i++) {
        gpioSetMode(GPIO_PINS[i], PI_OUTPUT);
        gpioWrite(GPIO_PINS[i], 0); // Initialize to LOW
    }

    signal(SIGINT, signal_handler);

    printf("Starting program. Press Ctrl+C to terminate.\n");

    for (i = 0; i < CYCLES; i++) {
        current_state = 0; // Reset current state for each cycle
        for (int j = 0; j < NUM_PINS; j++) {
            gpioWrite(GPIO_PINS[j], current_state);
            current_state = 1 - current_state; // Toggle the state
        }
        printf("Cycle %d: ", i + 1);
        for (int j = 0; j < NUM_PINS; j++) {
            printf("%d ", gpioRead(GPIO_PINS[j]));
        }
        printf("\n");
        fflush(stdout); // Ensure output is displayed immediately
    }

    printf("Terminating program...\n");

    // Release GPIO pins
    for (i = 0; i < NUM_PINS; i++) {
        gpioWrite(GPIO_PINS[i], 0); // Set to LOW before exiting
        gpioSetMode(GPIO_PINS[i], PI_INPUT); // Set back to input
    }

    gpioTerminate();
    return 0;
}

