#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

void signal_handler(int sig);

int main() {
    int ret;
    struct gpiod_line_request_config config;

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    ret = gpiod_chip_open(GPIO_CHIP, &chip);
    if (ret < 0) {
        fprintf(stderr, "Error opening GPIO chip: %d\n", ret);
        return 1;
    }

    // Get GPIO line
    ret = gpiod_chip_get_line(chip, GPIO_PIN, &line);
    if (ret < 0) {
        fprintf(stderr, "Error getting GPIO line: %d\n", ret);
        gpiod_chip_close(chip);
        return 1;
    }

    // Configure GPIO line as output
    memset(&config, 0, sizeof(config));
    config.consumer = "my_gpio_consumer";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line: %d\n", ret);
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return 1;
    }

    // Set initial state to LOW
    ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error setting initial GPIO line value: %d\n", ret);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Toggle GPIO state
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            fprintf(stderr, "Error toggling GPIO line value: %d\n", ret);
            break;
        }
        usleep(100000); // 100ms

        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            fprintf(stderr, "Error toggling GPIO line value: %d\n", ret);
            break;
        }
        usleep(100000); // 100ms
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

