    gpioSetMode(GPIO_3, PI_OUTPUT);
    gpioSetMode(GPIO_5, PI_OUTPUT);

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        gpioWrite(GPIO_2, 1);
        gpioWrite(GPIO_3, 0);
        gpioWrite(GPIO_5, 1);
        printf("GPIO 2: %d, GPIO 3: %d, GPIO 5: %d\n", gpioRead(GPIO_2), gpioRead(GPIO_3), gpioRead(GPIO_5));
