        gpioWrite(GPIO_2, 0);
        gpioWrite(GPIO_3, 1);
        gpioWrite(GPIO_5, 0);
        printf("GPIO 2: %d, GPIO 3: %d, GPIO 5: %d\n", gpioRead(GPIO_2), gpioRead(GPIO_3), gpioRead(GPIO_5));
