#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int read_pulse_width() {
    int start_tick, end_tick, diff;

    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    // Wait for echo to go high (with timeout)
    int timeout = 10000; // 10ms timeout
    while (gpioRead(ECHO_PIN) == 0 && timeout > 0) {
        timeout--;
        gpioDelay(1); // Check every 1 us
    }

    if (timeout == 0) {
        fprintf(stderr, "Error: Echo signal not received (timeout)\n");
        return -1; // Indicate timeout error
    }

    start_tick = gpioTick();

    // Wait for echo to go low (with timeout)
    timeout = 10000; // 10ms timeout
    while (gpioRead(ECHO_PIN) == 1 && timeout > 0) {
        timeout--;
        gpioDelay(1); // Check every 1 us
    }

    if (timeout == 0) {
        fprintf(stderr, "Error: Echo signal not received (timeout)\n");
        return -1; // Indicate timeout error
    }

    end_tick = gpioTick();

    diff = end_tick - start_tick;
    return diff;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    printf("HC-SR04 Distance Measurement\n");

    while (!terminate) {
        int pulse_width = read_pulse_width();

        if (pulse_width > 0) {
            float distance = (pulse_width * 0.0343) / 2.0;
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Error reading pulse width\n");
        }

        gpioDelay(1000); // 1 second delay
    }

    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return 0;
}

