#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <time.h>

#define UART_PORT "/dev/ttyS0" // Or /dev/ttyAMA0
#define BAUD_RATE B115200
#define MAX_BUFFER 256

int serial_fd = -1; // Global file descriptor for serial port

// Structure to hold program state
typedef struct {
    int uart_fd;
    int running;
} ProgramState;

ProgramState state = {0, 1}; // Initialize running to 1

// Signal handler for Ctrl+C
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        state.running = 0; // Set running to 0 to exit the main loop

        if (serial_fd != -1) {
            close(serial_fd); // Close the serial port
        }

        exit(0); // Exit the program
    }
}

// Function to initialize the serial port
int init_serial(const char *port, speed_t baud_rate) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        perror("Error opening serial port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD;  // 8N1, no parity
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0; // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read doesn't block
    tty.c_cc[VTIME] = 5; // 0.5 seconds read timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read data from the serial port
int read_serial_data(int fd, char *buffer, int buffer_size) {
    ssize_t bytes_read = read(fd, buffer, buffer_size - 1);
    if (bytes_read == -1) {
        if (errno == EAGAIN || errno == EWOULDBLOCK) {
            // No data available, return 0
            return 0;
        }
        perror("Error reading from serial port");
        return -1;
    } else {
        buffer[bytes_read] = '\0'; // Null-terminate the buffer
        return (int)bytes_read;
    }
}

// Function to print the received data
void print_data(const char *data) {
    printf("Received: %s\n", data);
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize serial port
    serial_fd = init_serial(UART_PORT, BAUD_RATE);
    if (serial_fd == -1) {
        fprintf(stderr, "Failed to initialize serial port. Exiting.\n");
        return 1;
    }

    printf("Serial port initialized successfully. Waiting for data...\n");

    char buffer[MAX_BUFFER];
    int bytes_read;

    while (state.running) {
        bytes_read = read_serial_data(serial_fd, buffer, MAX_BUFFER);
        if (bytes_read > 0) {
            print_data(buffer);
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from serial port. Exiting.\n");
            break; // Exit the loop on error
        }
        usleep(10000); // Sleep for 10ms to avoid busy-waiting
    }

    // Cleanup: Close the serial port
    if (serial_fd != -1) {
        close(serial_fd);
    }

    printf("Program terminated.\n");
    return 0;
}

