#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define DEBOUNCE_DELAY_MS 50

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int gpio_status;
    int valid_reading = 0;
    int i;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 4 as an output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    printf("GPIO 4 (BCM %d) initialized as output. Press Ctrl+C to exit.\n", GPIO_PIN);

    while (program_running) {
        // Read the GPIO value
        gpio_status = gpioRead(GPIO_PIN);

        if (gpio_status < 0) {
            fprintf(stderr, "Error reading GPIO %d\n", GPIO_PIN);
            break; // Exit loop on error
        }

        // Debounce the reading
        gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Convert ms to microseconds

        // Check for valid reading (LOW)
        if (gpio_status == 0) {
            valid_reading = 1;
        } else {
            valid_reading = 0;
        }

        // Report the state
        printf("GPIO %d: %s\n", GPIO_PIN, valid_reading ? "LOW" : "HIGH");

        // Wait for a short period
        gpioDelay(100000); // 100ms
    }

    // Release GPIO 4
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

