    while (program_running) {
        // Read current GPIO state
        gpio_status = gpioRead(GPIO_PIN);

        // Debounce the input
        if (gpio_status != previous_state) {
            usleep(DEBOUNCE_DELAY_MS * 1000); // Convert ms to us
            gpio_status = gpioRead(GPIO_PIN); // Re-read after debounce
        }

        // If the state has stabilized, check if it has changed
        if (gpio_status == previous_state) {
            if (gpio_status != current_state) {
                current_state = gpio_status;
                printf("Current state: %d\n", current_state);

                // Toggle the output
                gpioWrite(GPIO_PIN, !current_state);
                previous_state = current_state;
            }
        }

        usleep(1000); // Check every 1ms
    }

    // Clean up and exit
    gpioWrite(GPIO_PIN, 0); // Set to LOW before exiting
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

