#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_CHIP_PATH "/sys/class/gpio/gpiochip0"
#define GPIO_2_PATH "/sys/class/gpio/gpio2/value"
#define GPIO_3_PATH "/sys/class/gpio/gpio3/value"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line2 = NULL;
static struct gpiod_line *line3 = NULL;

static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 100000000; // 100ms

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    // Get GPIO line 2
    line2 = gpiod_chip_get_line(chip, 2);
    if (!line2) {
        perror("Error getting GPIO line 2");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Get GPIO line 3
    line3 = gpiod_chip_get_line(chip, 3);
    if (!line3) {
        perror("Error getting GPIO line 3");
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO line 2 for output
    if (gpiod_line_request_output(line2, "test_output", 0) < 0) {
        perror("Error requesting GPIO line 2 for output");
        gpiod_line_release(line2);
        gpiod_line_release(line3);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO line 3 for output
    if (gpiod_line_request_output(line3, "test_output", 0) < 0) {
        perror("Error requesting GPIO line 3 for output");
        gpiod_line_release(line2);
        gpiod_line_release(line3);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop: set GPIO states and report
    for (int i = 0; i < 3; ++i) {
        // Set GPIO 2 to 1
        if (gpiod_line_set_value(line2, 1) < 0) {
            perror("Error setting GPIO 2 value");
            gpiod_line_release(line2);
            gpiod_line_release(line3);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        // Set GPIO 3 to 0
        if (gpiod_line_set_value(line3, 0) < 0) {
            perror("Error setting GPIO 3 value");
            gpiod_line_release(line2);
            gpiod_line_release(line3);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        // Report the state
        printf("Cycle %d: GPIO 2 (2) = 1, GPIO 3 (3) = 0\n", i + 1);

        // Wait for 100ms
        nanosleep(&sleep_time, NULL);
    }

    // Clean up: release GPIO lines and close chip
    gpiod_line_release(line2);
    gpiod_line_release(line3);
    gpiod_chip_close(chip);

    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

