#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define the GPIO pin for the DHT11 data line (BCM numbering)
#define DHT11_GPIO 4

// Define the SPI device and speed
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000 // 1 MHz

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signum) {
    if (signum == SIGINT) {
        program_running = 0;
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
    }
}

// Function to initialize the SPI interface
int spi_init(const char *device, int speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set SPI speed
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read data from the DHT11 sensor
int read_dht11(int fd, uint8_t *data) {
    uint8_t tx_buf[3] = {0x00, 0x00, 0x00};
    uint8_t rx_buf[3] = {0x00, 0x00, 0x00};

    // Send start signal
    if (write(fd, tx_buf, 3) != 3) {
        perror("Error writing to SPI device");
        return -1;
    }

    // Wait for a response (low signal)
    usleep(1000); // 1 ms

    // Read 4 bytes of data
    if (read(fd, rx_buf, 3) != 3) {
        perror("Error reading from SPI device");
        return -1;
    }

    // Verify checksum
    if (rx_buf[0] != rx_buf[1] || rx_buf[2] != rx_buf[2]) {
        fprintf(stderr, "Checksum error\n");
        return -1;
    }

    // Extract data
    data[0] = rx_buf[0];
    data[1] = rx_buf[1];
    data[2] = rx_buf[2];

    return 0;
}

// Function to process the DHT11 data
int process_dht11_data(uint8_t *data) {
    // Check for valid data (5 bytes, first byte is 0x80)
    if (data[0] != 0x80 || data[1] != 0x80 || data[2] != 0x80 || data[3] != 0x80) {
        fprintf(stderr, "Invalid data received\n");
        return -1;
    }

    // Extract humidity and temperature
    int humidity = (data[0] << 8) | data[1];
    int temperature = (data[2] << 8) | data[3];

    // Validate temperature
    if (temperature > 125 || temperature < -40) {
        fprintf(stderr, "Temperature out of range: %d\n", temperature);
        return -1;
    }

    return 0;
}

// Function to report the DHT11 data
void report_dht11_data(int gpio, uint8_t *data) {
    printf("GPIO %d: Humidity = %d%%, Temperature = %d°C\n", gpio, data[0], data[2]);
}

int main() {
    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize SPI
    int spi_fd = spi_init(SPI_DEVICE, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return 1;
    }

    // Main loop
    while (program_running) {
        uint8_t dht11_data[4];

        // Read data from DHT11
        if (read_dht11(spi_fd, dht11_data) == 0) {
            // Process the data
            if (process_dht11_data(dht11_data) == 0) {
                // Report the data
                report_dht11_data(DHT11_GPIO, dht11_data);
            }
        } else {
            fprintf(stderr, "Failed to read DHT11 data\n");
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Close SPI device
    close(spi_fd);

    return 0;
}

