static struct gpiod_line *line18 = NULL;
static struct gpiod_line *line27 = NULL;

static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int ret;
    char *chip_name = getenv("HOME");
    if (chip_name == NULL) {
        fprintf(stderr, "Error: HOME environment variable not set. Using default 'gpiochip0'.\n");
        chip_name = "gpiochip0";
    }

    printf("Using GPIO chip: %s\n", chip_name);

    // Register signal handler for graceful exit
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(chip_name);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", chip_name, strerror(errno));
