    }

    // Get GPIO lines
    line17 = gpiod_chip_get_line(chip, GPIO_17);
    line18 = gpiod_chip_get_line(chip, GPIO_18);
    line27 = gpiod_chip_get_line(chip, GPIO_27);

    if (!line17 || !line18 || !line27) {
        fprintf(stderr, "Error getting GPIO line(s): %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO lines for output
    ret = gpiod_line_request_output(line17, "output17", 0); // Initial value 0
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO %d for output: %s\n", GPIO_17, strerror(errno));
        gpiod_line_release(line17);
        gpiod_line_release(line18);
        gpiod_line_release(line27);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line18, "output18", 0); // Initial value 0
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO %d for output: %s\n", GPIO_18, strerror(errno));
        gpiod_line_release(line17);
        gpiod_line_release(line18);
        gpiod_line_release(line27);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line27, "output27", 0); // Initial value 0
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO %d for output: %s\n", GPIO_27, strerror(errno));
        gpiod_line_release(line17);
        gpiod_line_release(line18);
        gpiod_line_release(line27);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        printf("GPIO 17: %d\n", gpiod_line_get_value(line17));
        printf("GPIO 18: %d\n", gpiod_line_get_value(line18));
        printf("GPIO 27: %d\n", gpiod_line_get_value(line27));
        sleep(1);
    }

    // Release GPIO lines
    gpiod_line_release(line17);
    gpiod_line_release(line18);
    gpiod_line_release(line27);

    // Close GPIO chip
    gpiod_chip_close(chip);

