#define GPIO_PIN 18
#define CIRCULAR_BUFFER_SIZE 10

// Circular buffer for GPIO state
int gpio_states[CIRCULAR_BUFFER_SIZE];
int buffer_index = 0;

// Function to set the GPIO state
void set_gpio_state(int state) {
    gpioWrite(GPIO_PIN, state);
}

// Function to add a state to the circular buffer
void add_to_buffer(int state) {
    gpio_states[buffer_index] = state;
    buffer_index = (buffer_index + 1) % CIRCULAR_BUFFER_SIZE;
}

// Function to print the current state and the circular buffer
void print_state() {
    printf("Current GPIO state: %s\n", gpio_states);
    printf("Circular buffer contents: ");
    for (int i = 0; i < CIRCULAR_BUFFER_SIZE; i++) {
        printf("%d ", gpio_states[i]);
    }
    printf("\n");
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 18 as an output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initial state: LOW
    set_gpio_state(0);
    add_to_buffer(0);

    // Main loop
    while (1) {
        // Set GPIO state to HIGH
        set_gpio_state(1);
        add_to_buffer(1);

        // Wait for 0.1 seconds
        gpioDelay(100000); // 100 ms = 0.1 seconds

        // Set GPIO state to LOW
        set_gpio_state(0);
        add_to_buffer(0);

        // Wait for 0.1 seconds
        gpioDelay(100000); // 100 ms = 0.1 seconds

        // Print the current state and the circular buffer
        print_state();
    }

    // Cleanup (should not reach here in normal execution due to the infinite loop)
    gpioTerminate();
    return 0;
}

