#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define UART_PORT "/dev/ttyS0" // Or /dev/ttyAMA0
#define BAUD_RATE B115200
#define MAX_BUFFER 256
#define MAX_RETRIES 3

int serial_fd = -1;
volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

int setup_serial(const char *port, speed_t baud_rate) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        perror("Error opening serial port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud_rate);
    cfsetispeed(&tty, baud_rate);

    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~PARENB; // No parity
    tty.c_cflag &= ~CSTOPB; // 1 stop bit
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8; // 8 data bits
    tty.c_cflag &= ~CRTSCTS; // Disable hardware flow control
    tty.c_cflag |= CREAD | CLOCAL;

    tty.c_lflag &= ~ICANON; // Disable canonical mode
    tty.c_lflag &= ~ECHO;   // Disable echo
    tty.c_lflag &= ~ECHOE;  // Disable erasure
    tty.c_lflag &= ~ECHONL; // Disable new-line echo
    tty.c_lflag &= ~ISIG;   // Disable interpretation of INTR, QUIT and SUSP

    tty.c_iflag &= ~(IXON | IXOFF | IXANY); // Turn off software flow control
    tty.c_iflag &= ~(IGNBRK|BRKINT|PARMRK|ISTRIP|INLCR|IGNCR|ICRNL);

    tty.c_oflag &= ~OPOST; // Prevent special interpretation of output bytes (e.g. newline chars)
    tty.c_oflag &= ~ONLCR; // Prevent conversion of newline to carriage return/line feed

    tty.c_cc[VMIN] = 0;  // Read doesn't block
    tty.c_cc[VTIME] = 5; // 0.5 seconds read timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

int read_serial_data(int fd, char *buffer, int max_size) {
    ssize_t bytes_read = read(fd, buffer, max_size - 1);
    if (bytes_read == -1) {
        if (errno == EAGAIN || errno == EWOULDBLOCK) {
            // No data available, return 0
            return 0;
        } else {
            perror("Error reading from serial port");
            return -1;
        }
    } else if (bytes_read > 0) {
        buffer[bytes_read] = '\0'; // Null-terminate the buffer
        return bytes_read;
    } else {
        // No data available, return 0
        return 0;
    }
}

int main() {
    signal(SIGINT, signal_handler);

    serial_fd = setup_serial(UART_PORT, BAUD_RATE);
    if (serial_fd == -1) {
        fprintf(stderr, "Failed to setup serial port. Exiting.\n");
        return EXIT_FAILURE;
    }

    printf("Serial port setup complete. Waiting for device...\n");

    while (!terminate) {
        char buffer[MAX_BUFFER];
        int bytes_read = read_serial_data(serial_fd, buffer, MAX_BUFFER);

        if (bytes_read > 0) {
            printf("Received: %s\n", buffer);
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from serial port. Exiting.\n");
            break;
        } else {
            // Device not present or disconnected
            fprintf(stderr, "Device not present or disconnected. Exiting.\n");
            break;
        }

        usleep(100000); // 100ms delay
    }

    close(serial_fd);
    printf("Serial port closed. Exiting.\n");
    return EXIT_SUCCESS;
}

