#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 2
#define VALID_READING 1
#define INVALID_READING 0

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int gpio_status;
    int reading;

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 2 as an output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    printf("Program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Set GPIO high
        gpioWrite(GPIO_PIN, 1);
        gpioDelay(100000); // 100ms

        // Read the GPIO value
        reading = gpioRead(GPIO_PIN);

        // Check for errors during GPIO read
        if (reading == PI_BAD_GPIO) {
            fprintf(stderr, "Error reading GPIO %d\n", GPIO_PIN);
            gpioTerminate();
            return 1;
        }

        // Validate the reading
        if (reading == VALID_READING) {
            printf("Valid reading: %d\n", reading);
        } else {
            fprintf(stderr, "Invalid reading: %d\n", reading);
        }

        // Set GPIO low
        gpioWrite(GPIO_PIN, 0);
        gpioDelay(100000); // 100ms
    }

    // Terminate pigpio library
    gpioTerminate();

    printf("Program finished.\n");
    return 0;
}

