#define GPIO_2 2
#define GPIO_3 3

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int gpio_2_state, gpio_3_state;
    int valid_gpio_2_state, valid_gpio_3_state;

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 2 and GPIO 3 as outputs
    gpioSetMode(GPIO_2, PI_OUTPUT);
    gpioSetMode(GPIO_3, PI_OUTPUT);

    // Main loop
    while (!terminate) {
        // Read GPIO 2 state
        gpio_2_state = gpioRead(GPIO_2);
        valid_gpio_2_state = (gpio_2_state == 0 || gpio_2_state == 1); // Valid state is 0 or 1

        // Read GPIO 3 state
        gpio_3_state = gpioRead(GPIO_3);
        valid_gpio_3_state = (gpio_3_state == 0 || gpio_3_state == 1); // Valid state is 0 or 1

        // Check for errors and invalid readings
        if (gpio_2_state == PI_BAD_GPIO || gpio_3_state == PI_BAD_GPIO) {
            fprintf(stderr, "Error reading GPIO %d\n", (gpio_2_state == PI_BAD_GPIO) ? GPIO_2 : GPIO_3);
            gpioTerminate();
            return 1;
        }

        // Validate GPIO 2 state
        if (valid_gpio_2_state) {
            gpioWrite(GPIO_2, 1); // Set GPIO 2 to 1
        } else {
            fprintf(stderr, "Invalid state detected on GPIO %d, not setting output\n", (gpio_2_state == PI_BAD_GPIO) ? GPIO_2 : GPIO_3);
        }

        // Validate GPIO 3 state
        if (valid_gpio_3_state) {
            gpioWrite(GPIO_3, 1); // Set GPIO 3 to 1
        } else {
            fprintf(stderr, "Invalid state detected on GPIO %d, not setting output\n", (gpio_3_state == PI_BAD_GPIO) ? GPIO_3 : GPIO_2);
        }

        // Report the state
        printf("GPIO 2: %s, GPIO 3: %s\n", (gpio_2_state == 1) ? "HIGH" : "LOW", (gpio_3_state == 1) ? "HIGH" : "LOW");

        // Wait for 0.1 seconds
        gpioDelay(100000); // 100 ms = 0.1 seconds
    }

    // Clean up and exit
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return 0;
}

