int read_temperature(const char *device_id) {
    char filepath[256];
    char line[256];
    int fd;
    char *temp_str;
    float temperature = -127.0; // Error value
    int retries = 0;

    snprintf(filepath, sizeof(filepath), "%s%s/%s", W1_DEVICES_DIR, device_id, W1_SLAVE_FILE);

    while (retries < MAX_RETRIES) {
        fd = open(filepath, O_RDONLY);
        if (fd < 0) {
            fprintf(stderr, "Error opening %s: %s\n", filepath, strerror(errno));
            retries++;
            sleep(1); // Wait before retrying
            continue;
        }

        if (read(fd, line, sizeof(line)) > 0) {
            close(fd);

            // Check for CRC error
            if (strstr(line, "YES") != NULL) {
                // Extract temperature
                temp_str = strstr(line, "t=");
                if (temp_str != NULL) {
                    long temp_raw = strtol(temp_str + 2, NULL, 10);
                    temperature = (float)temp_raw / 1000.0;
                } else {
                    fprintf(stderr, "Error: Temperature data not found in %s\n", filepath);
                }
            } else {
                fprintf(stderr, "Error: CRC check failed in %s\n", filepath);
            }
        } else {
            fprintf(stderr, "Error reading from %s: %s\n", filepath, strerror(errno));
        }

        if (temperature != -127.0) {
            return temperature;
        }
    }

    fprintf(stderr, "Failed to read temperature from %s after %d retries.\n", device_id, MAX_RETRIES);
    return -127.0; // Indicate failure
}

