#include <string.h>

#define HTU21D_ADDR 0x40
#define TEMP_MEASURE_CMD 0xE3
#define HUMID_MEASURE_CMD 0xE5

int i2c_fd;

// Function to read temperature from HTU21D
float read_temperature() {
    uint8_t cmd = TEMP_MEASURE_CMD;
    uint8_t buf[3];
    int result;

    result = write(i2c_fd, &cmd, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing temperature command: %s\n", strerror(errno));
        return -1000.0; // Indicate error
    }

    usleep(50000); // Wait for measurement (at least 4.5ms)

    result = read(i2c_fd, buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading temperature data: %s\n", strerror(errno));
        return -1000.0; // Indicate error
    }

    uint16_t raw_temp = (buf[0] << 8) | buf[1];
    float temperature = -46.85 + 175.72 * ((float)raw_temp / 65536.0);
    return temperature;
}

// Function to read humidity from HTU21D
float read_humidity() {
    uint8_t cmd = HUMID_MEASURE_CMD;
    uint8_t buf[3];
    int result;

    result = write(i2c_fd, &cmd, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing humidity command: %s\n", strerror(errno));
        return -1000.0; // Indicate error
    }

    usleep(50000); // Wait for measurement (at least 4.5ms)

    result = read(i2c_fd, buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading humidity data: %s\n", strerror(errno));
        return -1000.0; // Indicate error
    }

    uint16_t raw_humidity = (buf[0] << 8) | buf[1];
    float humidity = -6.0 + 125.0 * ((float)raw_humidity / 65536.0);
    return humidity;
}

int main() {
    struct timespec sleep_time = {0, 60000000}; // 60 seconds
    float temperature, humidity;

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    while (1) {
        temperature = read_temperature();
        humidity = read_humidity();

        if (temperature > -999.0 && humidity > -999.0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Error reading sensor data. Check I2C connection.\n");
        }

        nanosleep(&sleep_time, NULL);
    }

    close(i2c_fd);
    return 0;
}

