            timeout++;
        }

        if (timeout >= 100) {
            fprintf(stderr, "DHT22 timeout error on pin %d\n", gpio_pin);
            return -1; // Timeout error
        }

        pulse_start = gpioTick();

        // Wait for the pin to go low
        timeout = 0;
        while (gpioRead(gpio_pin) == 1 && timeout < 100) {
            gpioDelay(1); // Wait 1us
            timeout++;
        }

        if (timeout >= 100) {
            fprintf(stderr, "DHT22 timeout error on pin %d (low)\n", gpio_pin);
            return -1; // Timeout error
        }

        pulse_end = gpioTick();

        // Calculate pulse width
        int pulse_width = pulse_end - pulse_start;

        // Determine bit value based on pulse width
        if (pulse_width > 40) {
            data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    // Verify checksum
    if ((data[0] + data[1] + data[2] + data[3]) != data[4]) {
        fprintf(stderr, "DHT22 checksum error on pin %d\n", gpio_pin);
        return -1; // Checksum error
    }

    // Convert data to temperature and humidity
    *humidity = (float)((data[0] << 8) + data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80) {
        *temperature = -*temperature;
    }

    return 0; // Success
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        float temperature1, humidity1, temperature2, humidity2, temperature3, humidity3, temperature4, humidity4;

        // Read data from DHT22 sensors
        if (read_dht22(DHT22_PIN_1, &temperature1, &humidity1) != 0) {
            fprintf(stderr, "Error reading DHT22 sensor on pin %d\n", DHT22_PIN_1);
        }
        if (read_dht22(DHT22_PIN_2, &temperature2, &humidity2) != 0) {
            fprintf(stderr, "Error reading DHT22 sensor on pin %d\n", DHT22_PIN_2);
        }
        if (read_dht22(DHT22_PIN_3, &temperature3, &humidity3) != 0) {
            fprintf(stderr, "Error reading DHT22 sensor on pin %d\n", DHT22_PIN_3);
        }
        if (read_dht22(DHT22_PIN_4, &temperature4, &humidity4) != 0) {
            fprintf(stderr, "Error reading DHT22 sensor on pin %d\n", DHT22_PIN_4);
        }

        // Print sensor data
        printf("Sensor 1: Temperature=%.1fC, Humidity=%.1f%%\n", temperature1, humidity1);
        printf("Sensor 2: Temperature=%.1fC, Humidity=%.1f%%\n", temperature2, humidity2);
        printf("Sensor 3: Temperature=%.1fC, Humidity=%.1f%%\n", temperature3, humidity3);
        printf("Sensor 4: Temperature=%.1fC, Humidity=%.1f%%\n", temperature4, humidity4);

