#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_CHIP_PATH "/sys/class/gpio/gpiochip0"
#define GPIO_2_PATH "/sys/class/gpio/gpio2/value"
#define GPIO_3_PATH "/sys/class/gpio/gpio3/value"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line2 = NULL;
static struct gpiod_line *line3 = NULL;

static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int ret;
    char value_path[64];
    struct gpiod_line_request_config config;

    // Register signal handler for graceful exit
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    ret = gpiod_chip_open(GPIO_CHIP, &chip);
    if (ret < 0) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Request GPIO 2
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio2_consumer";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    ret = gpiod_chip_request_lines(chip, &config, 1, &line2);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO 2: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO 3
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio3_consumer";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    ret = gpiod_chip_request_lines(chip, &config, 1, &line3);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO 3: %s\n", strerror(errno));
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        // Read GPIO 2 value
        snprintf(value_path, sizeof(value_path), "%s/value", GPIO_CHIP_PATH);
        ret = gpiod_line_get_value(line2);
        if (ret < 0) {
            fprintf(stderr, "Error reading GPIO 2 value: %s\n", strerror(errno));
            break;
        }
        int value2 = ret;

        // Read GPIO 3 value
        snprintf(value_path, sizeof(value_path), "%s/value", GPIO_CHIP_PATH);
        ret = gpiod_line_get_value(line3);
        if (ret < 0) {
            fprintf(stderr, "Error reading GPIO 3 value: %s\n", strerror(errno));
            break;
        }
        int value3 = ret;

        // Report GPIO 2 and GPIO 3 values
        printf("GPIO 2: %d, GPIO 3: %d\n", value2, value3);

        sleep(1);
    }

    // Release GPIO lines
    gpiod_line_release(line2);
    gpiod_line_release(line3);

    // Close GPIO chip
    ret = gpiod_chip_close(chip);
    if (ret < 0) {
        fprintf(stderr, "Error closing GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

