#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

// TCS34725 I2C address
#define TCS34725_ADDRESS 0x29

// TCS34725 register addresses
#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_CONTROL 0x8F
#define TCS34725_CDATA 0x94
#define TCS34725_RDATA 0x96
#define TCS34725_GDATA 0x98
#define TCS34725_BDATA 0x9A

// Function to write a byte to a TCS34725 register
int tcs34725_write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buffer[2];
    buffer[0] = reg;
    buffer[1] = value;
    if (write(fd, buffer, 2) != 2) {
        perror("Failed to write to TCS34725 register");
        return -1;
    }
    return 0;
}

// Function to read a byte from a TCS34725 register
int tcs34725_read_register(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address for read");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("Failed to read from TCS34725 register");
        return -1;
    }
    return 0;
}

// Function to read a word (2 bytes) from a TCS34725 register
int tcs34725_read_word(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buffer[2];
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address for read");
        return -1;
    }
    if (read(fd, buffer, 2) != 2) {
        perror("Failed to read from TCS34725 register");
        return -1;
    }
    *value = (buffer[0] << 8) | buffer[1];
    return 0;
}

// Function to initialize the TCS34725 sensor
int tcs34725_init(int fd) {
    // Enable the sensor (power on and enable RGBC)
    if (tcs34725_write_register(fd, TCS34725_ENABLE, 0x03) != 0) {
        fprintf(stderr, "Failed to enable TCS34725\n");
        return -1;
    }

    // Set integration time (ATIME) - 101ms
    if (tcs34725_write_register(fd, TCS34725_ATIME, 0xD5) != 0) {
        fprintf(stderr, "Failed to set integration time\n");
        return -1;
    }

    // Set gain (CONTROL) - 1x gain
    if (tcs34725_write_register(fd, TCS34725_CONTROL, 0x00) != 0) {
        fprintf(stderr, "Failed to set gain\n");
        return -1;
    }

    return 0;
}

int main() {
    int fd; // I2C file descriptor
    uint16_t clear, red, green, blue;

    // Open the I2C device
    if ((fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return 1;
    }

    // Initialize the TCS34725 sensor
    if (tcs34725_init(fd) != 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        close(fd);
        return 1;
    }

    // Main loop: read and print RGBC values every 0.2 seconds
    while (1) {
        // Read the RGBC values
        if (tcs34725_read_word(fd, TCS34725_CDATA, &clear) != 0) {
            fprintf(stderr, "Failed to read clear value\n");
        }
        if (tcs34725_read_word(fd, TCS34725_RDATA, &red) != 0) {
            fprintf(stderr, "Failed to read red value\n");
        }
        if (tcs34725_read_word(fd, TCS34725_GDATA, &green) != 0) {
            fprintf(stderr, "Failed to read green value\n");
        }
        if (tcs34725_read_word(fd, TCS34725_BDATA, &blue) != 0) {
            fprintf(stderr, "Failed to read blue value\n");
        }

        // Print the RGBC values
        printf("Clear: %u, Red: %u, Green: %u, Blue: %u\n", clear, red, green, blue);

        // Wait for 0.2 seconds
        usleep(200000); // 200ms = 0.2 seconds
    }

    // Close the I2C device (this will never be reached in the current loop)
    close(fd);

    return 0;
}

