#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_FORMAT "YUYV"
#define IMAGE_BUFFER_SIZE (IMAGE_WIDTH * IMAGE_HEIGHT * 2)

static volatile int keep_running = 1;

void int_handler(int dummy) {
    keep_running = 0;
}

int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    void *buffer = NULL;
    unsigned int n_buffers;
    unsigned int i;
    unsigned char *image_data = NULL;
    unsigned long image_size = 0;
    FILE *fp;
    struct v4l2_streamparm streamparm;
    struct v4l2_requestbufs req_new;
    struct v4l2_buffer buf_new;
    unsigned int i2;

    signal(SIGINT, int_handler);

    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening device");
        return 1;
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is no video capture device\n", DEVICE_NAME);
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", DEVICE_NAME);
        close(fd);
        return 1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(fd);
        return 1;
    }

    memset(&req, 0, sizeof(req));
    req.count = 1; // Single buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(fd);
        return 1;
    }

    buffer = mmap(NULL, IMAGE_BUFFER_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (buffer == MAP_FAILED) {
        perror("Error mapping buffer");
        close(fd);
        return 1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queueing buffer");
        munmap(buffer, IMAGE_BUFFER_SIZE);
        close(fd);
        return 1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        munmap(buffer, IMAGE_BUFFER_SIZE);
        close(fd);
        return 1;
    }

    image_data = (unsigned char *)buffer;
    image_size = IMAGE_WIDTH * IMAGE_HEIGHT * 2;

    fp = fopen("image.yuyv", "wb");
    if (fp == NULL) {
        perror("Error opening image file");
        munmap(buffer, IMAGE_BUFFER_SIZE);
        close(fd);
        return 1;
    }

    fwrite(image_data, 1, image_size, fp);
    fclose(fp);

    printf("Image saved to image.yuyv\n");

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queueing buffer");
        munmap(buffer, IMAGE_BUFFER_SIZE);
        close(fd);
        return 1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_RDBUF, &buf) < 0) {
        perror("Error reading buffer");
        munmap(buffer, IMAGE_BUFFER_SIZE);
        close(fd);
        return 1;
    }

    unsigned int n_buffers_read;
    if (ioctl(fd, VIDIOC_STREAMON, &streamparm) < 0) {
        perror("Error starting stream");
        munmap(buffer, IMAGE_BUFFER_SIZE);
        close(fd);
        return 1;
    }

    n_buffers_read = 1; // Capture one frame
    while (keep_running) {
        memset(&req_new, 0, sizeof(req_new));
        req_new.count = n_buffers_read;
        req_new.type = V4L2_BUF_TYPE_CAPTURE;
        req_new.memory = V4L2_MEMORY_MMAP;
        req_new.index = 0;

        if (ioctl(fd, VIDIOC_QBUF, &req_new) < 0) {
            perror("Error queueing buffers");
            break;
        }

        if (ioctl(fd, VIDIOC_RDBUF, &buf) < 0) {
            perror("Error reading buffer");
            break;
        }

        if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            perror("Error dequeuing buffer");
            break;
        }

        n_buffers_read++;
    }

    if (ioctl(fd, VIDIOC_STREAMOFF, &streamparm) < 0) {
        perror("Error stopping stream");
    }

    munmap(buffer, IMAGE_BUFFER_SIZE);
    close(fd);

    printf("Program finished\n");

    return 0;
}

