#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIG_PIN 17
#define ECHO_PIN 23

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        // Rising edge
        gpioSetTimerFuncEx(ECHO_PIN, 0, 0, NULL); // Disable further callbacks on this pin
    } else if (level == 0) {
        // Falling edge
        uint32_t start = tick;
        gpioSetTimerFuncEx(ECHO_PIN, 0, 0, NULL); // Disable further callbacks on this pin

        // Wait for the echo pulse to end (or timeout)
        while (gpioRead(ECHO_PIN) == 0 && !terminate) {
            usleep(1000); // Check every 1ms
        }

        uint32_t end = tick;
        uint32_t pulse_duration = end - start;

        if (!terminate) {
            printf("Pulse duration: %u us\n", pulse_duration);
        } else {
            printf("Timeout waiting for echo.\n");
        }
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    gpioWrite(TRIG_PIN, 0);
    gpioDelay(2);
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIG_PIN, 0);

    signal(SIGINT, signal_handler);

    gpioSetTimerFuncEx(ECHO_PIN, 50000, 0, echo_callback); // 50ms timeout

    while (!terminate) {
        gpioDelay(2000000); // 2 seconds
        gpioSetTimerFuncEx(ECHO_PIN, 0, 0, NULL); // Disable callback
        gpioSetTimerFuncEx(ECHO_PIN, 50000, 0, echo_callback); // Re-enable callback
    }

    gpioSetTimerFuncEx(ECHO_PIN, 0, 0, NULL); // Disable callback before exiting
    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define NUM_PIXELS 10

// Structure to hold pixel data
typedef struct {
    unsigned char red;
    unsigned char green;
    unsigned char blue;
} Pixel;

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
    }
}

// Function to set the color of a single pixel
void set_pixel(int pixel_index, Pixel pixel) {
    gpioPWM(GPIO_PIN, pixel.red); // Set PWM duty cycle for red
    gpioWrite(GPIO_PIN, 1); // Set GPIO high to set the color
    gpioDelay(100000); // Delay for 100ms (adjust for desired speed)
    gpioWrite(GPIO_PIN, 0); // Set GPIO low to clear the color
    gpioPWM(GPIO_PIN, pixel.green); // Set PWM duty cycle for green
    gpioDelay(100000); // Delay for 100ms
    gpioPWM(GPIO_PIN, pixel.blue); // Set PWM duty cycle for blue
    gpioDelay(100000); // Delay for 100ms
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 18 as an output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Pixel data (example: red, green, blue)
    Pixel pixels[NUM_PIXELS] = {
        {255, 0, 0},   // Red
        {0, 255, 0},   // Green
        {0, 0, 255},   // Blue
        {255, 255, 0}, // Yellow
        {255, 0, 255}, // Magenta
        {0, 255, 255}, // Cyan
        {255, 255, 255}, // White
        {0, 255, 255}, // Light Blue
        {255, 0, 255}, // Light Magenta
        {255, 255, 0}  // Light Yellow
    };

    // Main loop
    while (program_running) {
        for (int i = 0; i < NUM_PIXELS; i++) {
            set_pixel(i, pixels[i]);
        }
        gpioDelay(10000); // Delay for 10ms
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_CHIP_PATH "/sys/class/gpio/gpiochip0"
#define GPIO_17_PATH "/sys/class/gpio/gpio17/value"
#define GPIO_27_PATH "/sys/class/gpio/gpio27/value"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line17 = NULL;
static struct gpiod_line *line27 = NULL;

static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int ret;
    char value_path[64];
    struct gpiod_line_request_config config;

    // Register signal handler for graceful exit
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    // Get GPIO 17 line
    snprintf(value_path, sizeof(value_path), "%s/gpio17/value", GPIO_CHIP_PATH);
    line17 = gpiod_chip_get_line(chip, 17);
    if (!line17) {
        fprintf(stderr, "Error getting GPIO 17 line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Get GPIO 27 line
    snprintf(value_path, sizeof(value_path), "%s/gpio27/value", GPIO_CHIP_PATH);
    line27 = gpiod_chip_get_line(chip, 27);
    if (!line27) {
        fprintf(stderr, "Error getting GPIO 27 line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO 17 line for output
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio17_output";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    ret = gpiod_line_request(line17, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO 17 for output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO 27 line for output
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio27_output";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    ret = gpiod_line_request(line27, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO 27 for output: %s\n", strerror(errno));
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        // Set GPIO 17 to HIGH
        ret = gpiod_line_set_value(line17, 1);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO 17 to HIGH: %s\n", strerror(errno));
            break;
        }

        // Set GPIO 27 to LOW
        ret = gpiod_line_set_value(line27, 0);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO 27 to LOW: %s\n", strerror(errno));
            break;
        }

        // Report the current state
        printf("GPIO 17: %d, GPIO 27: %d\n", gpiod_line_get_value(line17), gpiod_line_get_value(line27));

        // Wait for 1 second
        sleep(1);
    }

    // Release GPIO lines
    gpiod_line_release(line17);
    gpiod_line_release(line27);

    // Close GPIO chip
    gpiod_chip_close(chip);

    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

