#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <string.h>

#define NUM_GPIOS 8

int main(int argc, char *argv[]) {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[NUM_GPIOS];
    int i;
    int ret;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <chip_name>\n", argv[0]);
        return EXIT_FAILURE;
    }

    char *chip_name = argv[1];

    chip = gpiod_chip_open_by_name(chip_name);
    if (!chip) {
        fprintf(stderr, "Error opening chip '%s': %s\n", chip_name, gpiod_strerror(chip->error));
        return EXIT_FAILURE;
    }

    for (i = 0; i < NUM_GPIOS; i++) {
        lines[i] = gpiod_chip_get_line(chip, i);
        if (!lines[i]) {
            fprintf(stderr, "Error getting line %d: %s\n", i, gpiod_strerror(lines[i]->error));
            goto cleanup;
        }

        ret = gpiod_line_request_output(lines[i], NULL, GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
        if (ret < 0) {
            fprintf(stderr, "Error requesting line %d as output: %s\n", i, gpiod_strerror(ret));
            goto cleanup;
        }
    }

    for (i = 0; i < NUM_GPIOS; i++) {
        ret = gpiod_line_set_value(lines[i], 1);
        if (ret < 0) {
            fprintf(stderr, "Error setting value for line %d: %s\n", i, gpiod_strerror(ret));
            goto cleanup;
        }
        printf("GPIO %d: %d\n", i, ret);
    }

cleanup:
    for (i = 0; i < NUM_GPIOS; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

