// BME280 I2C address
#define BME280_I2C_ADDR 0x76

// BME280 register addresses
#define BME280_REG_TEMP_MSB 0xFA
#define BME280_REG_PRESSURE_MSB 0xF7
#define BME280_REG_HUMIDITY_MSB 0xFD
#define BME280_REG_CTRL_MEAS 0xF4
#define BME280_REG_CTRL_HUM 0xF2
#define BME280_REG_CONFIG 0xF5
#define BME280_REG_ID 0xD0

// Calibration data registers
#define BME280_REG_CALIB_00 0x88

// Structure to hold calibration data
struct bme280_calib_data {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
    uint8_t dig_H1;
    int16_t dig_H2;
    uint8_t dig_H3;
    int16_t dig_H4;
    int16_t dig_H5;
    int8_t dig_H6;
};

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signum) {
    if (signum == SIGINT) {
        program_running = 0;
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
    }
}

// Function to read a single byte from the I2C device
int i2c_read_byte(int fd, uint8_t reg) {
    uint8_t buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, buf, 1) != 1) {
        perror("Failed to read data");
        return -1;
    }
    return buf[0];
}

// Function to write a single byte to the I2C device
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write data");
        return -1;
    }
    return 0;
}

// Function to read calibration data from the BME280
int read_calibration_data(int fd, struct bme280_calib_data *calib) {
    uint8_t data[26];
    if (i2c_read_i2c_block_data(fd, BME280_REG_CALIB_00, (char *)data, 26) != 26) {
        fprintf(stderr, "Failed to read calibration data\n");
        return -1;
    }

    calib->dig_T1 = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
    calib->dig_T2 = (int16_t)data[2] | ((int16_t)data[3] << 8);
    calib->dig_T3 = (int16_t)data[4] | ((int16_t)data[5] << 8);
    calib->dig_P1 = (uint16_t)data[6] | ((uint16_t)data[7] << 8);
    calib->dig_P2 = (int16_t)data[8] | ((int16_t)data[9] << 8);
    calib->dig_P3 = (int16_t)data[10] | ((int16_t)data[11] << 8);
    calib->dig_P4 = (int16_t)data[12] | ((int16_t)data[13] << 8);
    calib->dig_P5 = (int16_t)data[14] | ((int16_t)data[15] << 8);
    calib->dig_P6 = (int16_t)data[16] | ((int16_t)data[17] << 8);
    calib->dig_P7 = (int16_t)data[18] | ((int16_t)data[19] << 8);
    calib->dig_P8 = (int16_t)data[20] | ((int16_t)data[21] << 8);
    calib->dig_P9 = (int16_t)data[22] | ((int16_t)data[23] << 8);
    calib->dig_H1 = data[25];

    uint8_t data_h[7];
    if (i2c_read_i2c_block_data(fd, 0xE1, (char *)data_h, 7) != 7) {
        fprintf(stderr, "Failed to read humidity calibration data\n");
        return -1;
    }

    calib->dig_H2 = (int16_t)data_h[0] | ((int16_t)data_h[1] << 8);
    calib->dig_H3 = data_h[2];
    calib->dig_H4 = (int16_t)((data_h[3] << 4) | (data_h[4] & 0x0F));
    calib->dig_H5 = (int16_t)((data_h[5] << 4) | ((data_h[4] >> 4) & 0x0F));
    calib->dig_H6 = (int8_t)data_h[6];

    return 0;
}

// Function to read raw data from the BME280
int read_raw_data(int fd, int32_t *temperature, int32_t *pressure, int32_t *humidity) {
    uint8_t data[8];
    if (i2c_read_i2c_block_data(fd, BME280_REG_PRESSURE_MSB, (char *)data, 8) != 8) {
        fprintf(stderr, "Failed to read raw data\n");
        return -1;
    }

    *pressure = (int32_t)((((uint32_t)data[0] << 12) | ((uint32_t)data[1] << 4) | ((uint32_t)data[2] >> 4)));
    *temperature = (int32_t)((((uint32_t)data[3] << 12) | ((uint32_t)data[4] << 4) | ((uint32_t)data[5] >> 4)));
    *humidity = (int32_t)((((uint32_t)data[6] << 8) | (uint32_t)data[7]));

    return 0;
}

// Function to compensate temperature
float compensate_temperature(int32_t raw_temperature, struct bme280_calib_data *calib) {
    double var1, var2, T;
    var1 = (((double)raw_temperature) / 16384.0 - ((double)calib->dig_T1) / 1024.0) * ((double)calib->dig_T2);
    var2 = ((((double)raw_temperature) / 131072.0 - ((double)calib->dig_T1) / 8192.0) * (((double)raw_temperature) / 131072.0 - ((double)calib->dig_T1) / 8192.0)) * ((double)calib->dig_T3);
    double t_fine = (var1 + var2);
    T = (t_fine / 5120.0);
    return (float)T;
}

// Function to compensate pressure
float compensate_pressure(int32_t raw_pressure, int32_t t_fine, struct bme280_calib_data *calib) {
    double var1, var2, p;
    var1 = ((double)t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * ((double)calib->dig_P6) / 32768.0;
    var2 = var2 + var1 * ((double)calib->dig_P5) * 2.0;
    var2 = (var2 / 4.0) + (((double)calib->dig_P4) * 65536.0);
    var1 = (((double)calib->dig_P3) * var1 * var1 / 524288.0 + ((double)calib->dig_P2) * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * ((double)calib->dig_P1);
    if (var1 == 0)
    {
        return 0;
    }
    p = 1048576.0 - (double)raw_pressure;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = ((double)calib->dig_P9) * p * p / 2147483648.0;
    var2 = p * ((double)calib->dig_P8) / 32768.0;
    p = p + (var1 + var2 + ((double)calib->dig_P7)) / 16.0;
    return (float)p;
}

// Function to compensate humidity
float compensate_humidity(int32_t raw_humidity, int32_t t_fine, struct bme280_calib_data *calib) {
    double var_H;
    var_H = (((double)t_fine) - 76800.0);
    var_H = (raw_humidity - (((double)calib->dig_H4) * 64.0 + ((double)calib->dig_H5) / 16384.0 * var_H)) * (((double)calib->dig_H2) / 65536.0 * (1.0 + ((double)calib->dig_H6) / 67108864.0 * var_H * (1.0 + ((double)calib->dig_H3) / 67108864.0 * var_H)));
    var_H = var_H * (1.0 - ((double)calib->dig_H1) * var_H / 524288.0);
    if (var_H > 100.0)
    {
        var_H = 100.0;
    } else if (var_H < 0.0)
    {
        var_H = 0.0;
    }
    return (float)var_H;
}

int main() {
    int fd;
    struct bme280_calib_data calib;
    int32_t raw_temperature, raw_pressure, raw_humidity;
    float temperature, pressure, humidity;
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Specify the address of the slave device
    if (ioctl(fd, I2C_SLAVE, BME280_I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return EXIT_FAILURE;
    }

    // Check the device ID
    uint8_t id;
    if (i2c_read_byte(fd, BME280_REG_ID) < 0) {
        fprintf(stderr, "Failed to read BME280 ID\n");
        close(fd);
        return EXIT_FAILURE;
    }
    id = i2c_read_byte(fd, BME280_REG_ID);
    if (id != 0x60) {
        fprintf(stderr, "Incorrect BME280 ID: 0x%02X\n", id);
        close(fd);
        return EXIT_FAILURE;
    }

    // Read calibration data
    if (read_calibration_data(fd, &calib) < 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        close(fd);
        return EXIT_FAILURE;
    }

    // Set humidity oversampling to 1x
    if (i2c_write_byte(fd, BME280_REG_CTRL_HUM, 0x01) < 0) {
        fprintf(stderr, "Failed to write humidity control register\n");
        close(fd);
        return EXIT_FAILURE;
    }

    // Set temperature and pressure oversampling to 1x and mode to normal
    if (i2c_write_byte(fd, BME280_REG_CTRL_MEAS, 0x27) < 0) {
        fprintf(stderr, "Failed to write control measurement register\n");
        close(fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (program_running) {
        // Read raw data
        if (read_raw_data(fd, &raw_temperature, &raw_pressure, &raw_humidity) < 0) {
            fprintf(stderr, "Failed to read raw data\n");
            continue; // Continue to the next iteration
        }

        // Compensate data
        temperature = compensate_temperature(raw_temperature, &calib);
        pressure = compensate_pressure(raw_pressure, (int32_t)(temperature * 5120.0), &calib);
        humidity = compensate_humidity(raw_humidity, (int32_t)(temperature * 5120.0), &calib);

        // Get current timestamp
        time(&current_time);
        time_info = localtime(&current_time);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

        // Print the data
        printf("%s - Temperature: %.2f °C, Pressure: %.2f hPa, Humidity: %.2f %%\n", timestamp, temperature, pressure, humidity);

        // Wait for 5 seconds
        sleep(5);
    }

    // Close I2C device
    close(fd);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define REF_VOLTAGE 4.096

int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the I2C bus
int init_i2c(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return fd;
}

// Function to configure the ADS1115
int configure_ads1115(int fd) {
    uint8_t config[3];
    config[0] = CONFIG_REG;
    config[1] = 0xC2; // Single-shot mode, AIN0, +/-4.096V, 128 SPS
    config[2] = 0x83; // Start single conversion

    if (write(fd, config, 3) != 3) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// Function to read the conversion register
int read_conversion(int fd) {
    uint8_t reg = CONVERSION_REG;
    uint8_t data[2];

    if (write(fd, &reg, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    if (read(fd, data, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    return (data[0] << 8) | data[1];
}

// Function to convert the raw reading to a voltage
float convert_to_voltage(int raw_value) {
    return ((float)raw_value * REF_VOLTAGE) / 32768.0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        return 1;
    }

    // Configure ADS1115
    if (configure_ads1115(i2c_fd) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read the conversion register
        int raw_value = read_conversion(i2c_fd);
        if (raw_value < 0) {
            fprintf(stderr, "Error reading conversion register, retrying in 0.2 seconds...\n");
            sleep(0.2);
            continue;
        }

        // Convert to voltage
        float voltage = convert_to_voltage(raw_value);

        // Print the voltage
        printf("Voltage: %.3f V\n", voltage);

        // Wait for 0.2 seconds
        sleep(0.2);
    }

    // Close I2C bus (this part is never reached in the current loop)
    close(i2c_fd);

    return 0;
}

