#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B

int i2c_fd;

int main() {
    const char *i2c_device = "/dev/i2c-1";
    int16_t accel_x, accel_y, accel_z;

    // Open I2C device
    if ((i2c_fd = open(i2c_device, O_RDWR)) < 0) {
        perror("Error opening I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Wake up the MPU6050
    uint8_t wake_up_data[2] = {PWR_MGMT_1, 0x00};
    if (write(i2c_fd, wake_up_data, 2) != 2) {
        perror("Error writing to I2C device");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read accelerometer data
        uint8_t reg = ACCEL_XOUT_H;
        if (write(i2c_fd, &reg, 1) != 1) {
            perror("Error writing to I2C device");
            close(i2c_fd);
            return 1;
        }

        uint8_t buffer[6];
        if (read(i2c_fd, buffer, 6) != 6) {
            perror("Error reading from I2C device");
            close(i2c_fd);
            return 1;
        }

        accel_x = (int16_t)((buffer[0] << 8) | buffer[1]);
        accel_y = (int16_t)((buffer[2] << 8) | buffer[3]);
        accel_z = (int16_t)((buffer[4] << 8) | buffer[5]);

        // Print the readings
        printf("Accelerometer readings: X=%d, Y=%d, Z=%d\n", accel_x, accel_y, accel_z);

        // Wait 100ms
        usleep(100000);
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

