#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 22

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 500000       // Timeout for echo pulse in microseconds (0.5 seconds)

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal)
{
    terminate = 1;
}

// Function to trigger the HC-SR04 sensor
void trigger_sensor()
{
    gpioWrite(TRIGGER_PIN, 1); // Set trigger pin high
    gpioDelay(10);             // Wait for 10 microseconds
    gpioWrite(TRIGGER_PIN, 0); // Set trigger pin low
}

// Function to measure the pulse width of the echo signal
long measure_pulse_width()
{
    long start_tick, end_tick, diff;

    // Wait for echo pin to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US)
    {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= TIMEOUT_US)
    {
        fprintf(stderr, "Error: Timeout waiting for echo high.\n");
        return -1; // Timeout error
    }

    start_tick = gpioTick();

    // Wait for echo pin to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US)
    {
        count++;
        gpioDelay(1);
    }

    if (count >= TIMEOUT_US)
    {
        fprintf(stderr, "Error: Timeout waiting for echo low.\n");
        return -1; // Timeout error
    }

    end_tick = gpioTick();

    diff = end_tick - start_tick;
    return diff;
}

// Function to calculate the distance in centimeters
float calculate_distance(long pulse_width)
{
    if (pulse_width < 0)
    {
        return -1.0; // Indicate error
    }
    return (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Convert microseconds to seconds and divide by 2
}

// Function to print the distance
void print_distance(float distance)
{
    if (distance >= 0)
    {
        printf("Distance: %.2f cm\n", distance);
    }
    else
    {
        printf("Error: Invalid distance reading.\n");
    }
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Main loop
    while (!terminate)
    {
        trigger_sensor();
        long pulse_width = measure_pulse_width();

        if (pulse_width >= 0)
        {
            float distance = calculate_distance(pulse_width);
            print_distance(distance);
        }
        else
        {
            fprintf(stderr, "Error: Failed to measure distance.\n");
        }

        gpioDelay(100); // Wait 0.1 seconds
    }

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated cleanly.\n");
    return 0;
}

