// Configuration
#define MQTT_BROKER "localhost" // Change to your broker address
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/sensor/temperature"
#define MQTT_CLIENT_ID "rpi_sensor_client"
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0 // MCP3008 channel connected to temperature sensor

// Global variables
volatile sig_atomic_t running = 1;
int socket_fd = -1;
struct mosquitto *mosq = NULL;

// Function prototypes
void signal_handler(int sig);
int read_mcp3008(int channel);
float convert_adc_to_temperature(int adc_value);
int publish_mqtt(float temperature);
void *spi_thread(void *arg);

// Signal handler
void signal_handler(int sig) {
    running = 0;
    printf("Caught signal %d, exiting...\n", sig);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char buffer[3];
    int adc_value = 0;

    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00;

    wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3);

    adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];

    return adc_value;
}

// Function to convert ADC value to temperature (Celsius)
float convert_adc_to_temperature(int adc_value) {
    // Assuming a simple linear relationship for demonstration
    // Replace with your actual sensor's calibration data
    float temperature = (adc_value / 1023.0) * 50.0 - 20.0; // Example: 0-1023 -> -20 to 70 C
    return temperature;
}

// Function to publish temperature to MQTT broker
int publish_mqtt(float temperature) {
    char payload[50];
    snprintf(payload, sizeof(payload), "%.2f", temperature);

    int ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing message: %s\n", mosquitto_strerror(ret));
        return -1;
    }
    return 0;
}

// SPI thread function
void *spi_thread(void *arg) {
    while (running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        float temperature = convert_adc_to_temperature(adc_value);

        printf("ADC Value: %d, Temperature: %.2f C\n", adc_value, temperature);

        if (publish_mqtt(temperature) != 0) {
            fprintf(stderr, "Failed to publish temperature.\n");
        }

        delay(1000); // Read every 1 second
    }
    return NULL;
}

int main() {
    // Initialize WiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "WiringPi initialization failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize SPI
    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) == -1) {
        fprintf(stderr, "SPI initialization failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        fprintf(stderr, "MQTT client initialization failed: %s\n", strerror(errno));
        return 1;
    }

    int ret = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "MQTT connection failed: %s\n", mosquitto_strerror(ret));
        mosquitto_destroy(mosq);
        mosq = NULL;
        mosquitto_lib_cleanup();
        return 1;
    }

    mosquitto_loop_start(mosq);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create SPI thread
    pthread_t spi_thread_id;
    if (pthread_create(&spi_thread_id, NULL, spi_thread, NULL) != 0) {
        fprintf(stderr, "Failed to create SPI thread: %s\n", strerror(errno));
        running = 0; // Stop the main loop
    }

    // Main loop (optional, can be used for other tasks)
    while (running) {
        delay(1000); // Sleep for 1 second
    }

    // Cleanup
    printf("Cleaning up...\n");
    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    pthread_join(spi_thread_id, NULL);

    if (socket_fd != -1) {
        close(socket_fd);
    }

    printf("Exiting.\n");
    return 0;
}

