#include <wiringPi.h>
#include <wiringPiSPI.h>
#include <mosquitto.h>

// Configuration
#define MQTT_BROKER_ADDRESS "localhost" // Change this to your broker address
#define MQTT_BROKER_PORT 1883
#define MQTT_CLIENT_ID "rpi_sensor_node"
#define MQTT_TOPIC "home/automation/sensor_data"
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0 // MCP3008 channel to read
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

// Global variables
static volatile int running = 1;
static struct mosquitto *mosq = NULL;

// Function prototypes
int read_mcp3008(int channel);
int validate_reading(int raw_reading);
int publish_mqtt(int raw_reading);
void signal_handler(int signum);

// Signal handler
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("Received SIGINT, exiting gracefully.\n");
        running = 0;
    }
}

// Reads the analog value from the MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char buffer[3];
    int adc_value = 0;

    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00;

    wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3);

    adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];

    return adc_value;
}

// Validates the raw reading
int validate_reading(int raw_reading) {
    // Define a reasonable range for the sensor reading
    int min_valid_reading = 0;
    int max_valid_reading = 1023;

    if (raw_reading < min_valid_reading || raw_reading > max_valid_reading) {
        fprintf(stderr, "Error: Invalid reading: %d\n", raw_reading);
        return -1; // Indicate an invalid reading
    }

    return raw_reading;
}

// Publishes the reading to the MQTT broker
int publish_mqtt(int raw_reading) {
    char payload[20];
    int rc;

    snprintf(payload, sizeof(payload), "%d", raw_reading);

    rc = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing message: %s\n", mosquitto_strerror(rc));
        return -1;
    }

    return 0;
}

int main() {
    int raw_reading;
    int retries;
    int result;

    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize SPI
    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) == -1) {
        fprintf(stderr, "Error initializing SPI: %s\n", strerror(errno));
        return 1;
    }

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error creating mosquitto instance\n");
        return 1;
    }

    mosquitto_connect_callback_set(mosq, NULL);
    mosquitto_message_callback_set(mosq, NULL);

    result = mosquitto_connect(mosq, MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT, 60);
    if (result != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(result));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return 1;
    }

    result = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    if (result != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error subscribing to topic: %s\n", mosquitto_strerror(result));
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);

    printf("Starting sensor data collection and publishing...\n");

    while (running) {
        raw_reading = read_mcp3008(MCP3008_CHANNEL);
        retries = 0;

        while (retries < MAX_RETRIES) {
            int validated_reading = validate_reading(raw_reading);
            if (validated_reading != -1) {
                if (publish_mqtt(validated_reading) == 0) {
                    printf("Published reading: %d\n", validated_reading);
                    break; // Exit retry loop on success
                } else {
                    fprintf(stderr, "Failed to publish reading, retry %d\n", retries + 1);
                }
            } else {
                fprintf(stderr, "Invalid reading, retry %d\n", retries + 1);
            }
            retries++;
            delay(RETRY_DELAY_MS);
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to validate reading after %d retries, skipping.\n", MAX_RETRIES);
        }

        delay(1000); // Delay between readings
    }

    // Disconnect from MQTT broker
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();

    printf("Exiting.\n");
    return 0;
}

