#define UART_PORT "/dev/ttyS0" // Or /dev/ttyAMA0
#define BAUD_RATE B115200
#define MAX_BUFFER 256

int serial_fd = -1; // Global serial file descriptor

// Signal handler for Ctrl+C
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("\nCtrl+C pressed. Exiting gracefully...\n");
        if (serial_fd != -1) {
            close(serial_fd);
        }
        exit(0);
    }
}

// Function to initialize the serial port
int init_serial(const char *port) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        perror("Error opening serial port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;     // 8-bit chars
    tty.c_iflag &= ~IGNBRK;         // disable break processing
    tty.c_lflag = 0;                // no signaling chars, no echo, no canonical processing
    tty.c_oflag = 0;                // no remapping, no delays
    tty.c_cc[VMIN]  = 0;            // read doesn't block
    tty.c_cc[VTIME] = 5;            // 0.5 seconds read timeout

    tty.c_iflag &= ~(IXON | IXOFF | IXANY); // shut off xon/xoff ctrl

    tty.c_cflag |= (CLOCAL | CREAD);   // ignore modem controls, enable reading
    tty.c_cflag &= ~(PARENB | PARODD); // shut off parity
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    if (cfsetospeed(&tty, BAUD_RATE) != 0 || cfsetispeed(&tty, BAUD_RATE) != 0) {
        perror("Error setting baud rate");
        close(fd);
        return -1;
    }

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read data from the serial port
int read_serial_data(int fd, char *buffer, int max_len) {
    ssize_t bytes_read = read(fd, buffer, max_len - 1);
    if (bytes_read == -1) {
        if (errno == EAGAIN || errno == EWOULDBLOCK) {
            // No data available, return 0
            return 0;
        }
        perror("Error reading from serial port");
        return -1;
    } else if (bytes_read > 0) {
        buffer[bytes_read] = '\0'; // Null-terminate the buffer
        return bytes_read;
    } else {
        return 0; // No data available
    }
}

// Function to print the received data
void print_data(const char *data) {
    printf("%s\n", data);
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize serial port
    serial_fd = init_serial(UART_PORT);
    if (serial_fd == -1) {
        return 1;
    }

    char buffer[MAX_BUFFER];
    int bytes_read;

    printf("Serial port initialized. Reading data...\n");

    while (1) {
        bytes_read = read_serial_data(serial_fd, buffer, MAX_BUFFER);
        if (bytes_read > 0) {
            print_data(buffer);
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from serial port. Exiting.\n");
            break;
        }
        usleep(100000); // 100ms delay
    }

    // Close the serial port
    close(serial_fd);

    return 0;
}

