double bmp280_compensate_pressure(int32_t raw_pressure, int32_t t_fine, int32_t *calibration_data) {
    double var1, var2, p;
    var1 = ((double)t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * ((double)calibration_data[0]) / 32768.0;
    var2 = var2 + var1 * ((double)calibration_data[1]) * 2.0;
    var2 = (var2 / 4.0) + (((double)calibration_data[2]) * 65536.0);
    var1 = (((double)calibration_data[3]) * var1 * var1 / 524288.0 + ((double)calibration_data[3]) * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * ((double)calibration_data[4]);
    if (var1 == 0)
    {
        return 0;
    }
    p = 1048576.0 - (double)raw_pressure;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = ((double)calibration_data[0]) * p * p / 2147483648.0;
    var2 = p * ((double)calibration_data[1]) / 32768.0;
    p = p + (var1 + var2 + ((double)calibration_data[2])) / 16.0;
    return p;
}

int main() {
    int i2c_fd;
    int32_t raw_temperature, raw_pressure, t_fine;
    double temperature, pressure;
    int32_t calibration_data[26];

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BMP280_I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Check if the BMP280 is present by reading the ID register
    int chip_id = bmp280_read_byte(i2c_fd, BMP280_REG_ID);
    if (chip_id < 0) {
        fprintf(stderr, "Error reading BMP280 ID register, check if the device is present.\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (chip_id != 0x58) {
        fprintf(stderr, "BMP280 not found, ID: 0x%02X\n", chip_id);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Read calibration data
    if (bmp280_read_calibration_data(i2c_fd, calibration_data) < 0) {
        fprintf(stderr, "Error reading calibration data.\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Set the BMP280 to forced mode and configure the sensor
    if (bmp280_write_byte(i2c_fd, BMP280_REG_CTRL_MEAS, 0x27) < 0) { // Oversampling x1, Normal mode
        fprintf(stderr, "Error writing to CTRL_MEAS register.\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (program_running) {
        // Read raw data
        if (bmp280_read_raw_data(i2c_fd, &raw_temperature, &raw_pressure) < 0) {
            fprintf(stderr, "Error reading raw data.\n");
            break;
        }

        // Compensate temperature and pressure
        temperature = bmp280_compensate_temperature(raw_temperature, &t_fine, calibration_data);
        pressure = bmp280_compensate_pressure(raw_pressure, t_fine, calibration_data);

        // Print the results
        printf("Temperature: %.2f \u00b0C, Pressure: %.2f Pa\n", temperature, pressure);

        // Wait for 5 seconds
        sleep(5);
    }

    // Close I2C device
    close(i2c_fd);

    return EXIT_SUCCESS;
}

