#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pthread.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>
#include <mosquitto.h>

// Configuration
#define MQTT_BROKER_ADDRESS "localhost" // Change to your broker address
#define MQTT_BROKER_PORT 1883
#define MQTT_CLIENT_ID "rpi_sensor_node"
#define MQTT_TOPIC "home/automation/sensor_data"
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0 // MCP3008 channel to read

// Global variables
volatile sig_atomic_t program_running = 1;
struct mosquitto *mosq = NULL;

// Function prototypes
int read_mcp3008(int channel);
void *sensor_reading_thread(void *arg);
void signal_handler(int signum);
int mqtt_connect_and_subscribe(struct mosquitto **mosq);
void mqtt_publish(struct mosquitto *mosq, const char *topic, const char *payload);
void cleanup(struct mosquitto *mosq);

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char buffer[3];
    int adc_value = 0;

    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00;

    wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3);

    adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];

    return adc_value;
}

// Function to publish sensor data to MQTT
void mqtt_publish(struct mosquitto *mosq, const char *topic, const char *payload) {
    int ret = mosquitto_publish(mosq, NULL, topic, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing message: %s\n", mosquitto_strerror(ret));
    }
}

// Function to connect to MQTT broker and subscribe to topic
int mqtt_connect_and_subscribe(struct mosquitto **mosq) {
    int ret = mosquitto_connect(*mosq, MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(ret));
        return -1;
    }

    ret = mosquitto_subscribe(*mosq, NULL, MQTT_TOPIC, 0);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error subscribing to topic: %s\n", mosquitto_strerror(ret));
        mosquitto_disconnect(*mosq);
        return -1;
    }

    return 0;
}

// Thread function to read sensor data and publish to MQTT
void *sensor_reading_thread(void *arg) {
    while (program_running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        char *payload = (char *)malloc(20 * sizeof(char)); // Allocate memory for the payload
        if (payload == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            break;
        }
        sprintf(payload, "%d", adc_value); // Convert ADC value to string

        mqtt_publish(mosq, MQTT_TOPIC, payload);
        free(payload); // Free allocated memory

        delay(1000); // Wait 1 second
    }
    return NULL;
}

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    program_running = 0;
    printf("Signal received, exiting...\n");
}

// Cleanup function to disconnect from MQTT and release resources
void cleanup(struct mosquitto *mosq) {
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
    }
    mosquitto_lib_cleanup();
}

int main() {
    // Initialize WiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "WiringPi initialization failed!\n");
        return 1;
    }

    // Initialize SPI
    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) == -1) {
        fprintf(stderr, "SPI initialization failed!\n");
        return 1;
    }

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error creating MQTT client instance!\n");
        return 1;
    }

    if (mqtt_connect_and_subscribe(&mosq) != 0) {
        cleanup(mosq);
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create sensor reading thread
    pthread_t sensor_thread;
    if (pthread_create(&sensor_thread, NULL, sensor_reading_thread, NULL) != 0) {
        fprintf(stderr, "Error creating sensor reading thread!\n");
        cleanup(mosq);
        return 1;
    }

    // Wait for the thread to finish (which it won't, but it's good practice)
    pthread_join(sensor_thread, NULL);

    // Cleanup and exit
    cleanup(mosq);
    return 0;
}

