#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_FORMAT "YUYV"

static volatile int keep_running = 1;

void int_handler(int dummy) {
    keep_running = 0;
}

int open_camera(const char *device_name) {
    int fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening camera");
        return -1;
    }
    return fd;
}

int set_image_format(int fd, const char *format) {
    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = v4l2_pix_format(format);
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting image format");
        return -1;
    }
    return 0;
}

int capture_image(int fd, const char *filename) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        perror("Error opening file for writing");
        return -1;
    }

    fwrite(buf.data, 1, buf.bytesused, fp);
    fclose(fp);

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        return -1;
    }

    if (ioctl(fd, VIDIOC_STREAMON, &buf.type) < 0) {
        perror("Error starting stream");
        return -1;
    }

    return 0;
}

int main() {
    signal(SIGINT, int_handler);

    int fd = open_camera(DEVICE_NAME);
    if (fd < 0) {
        fprintf(stderr, "Camera not found. Exiting.\n");
        return 1;
    }

    if (set_image_format(fd, IMAGE_FORMAT) < 0) {
        fprintf(stderr, "Failed to set image format. Exiting.\n");
        close(fd);
        return 1;
    }

    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture. Exiting.\n");
        close(fd);
        return 1;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 1; // Single buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(fd);
        return 1;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("Error querying buffer");
        close(fd);
        return 1;
    }

    struct v4l2_buffer *buffers = calloc(1, sizeof(struct v4l2_buffer));
    if (!buffers) {
        perror("Out of memory");
        close(fd);
        return 1;
    }

    buffers->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buffers->memory = V4L2_MEMORY_MMAP;
    buffers->index = 0;

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        close(fd);
        return 1;
    }

    if (ioctl(fd, VIDIOC_STREAMON, &buf.type) < 0) {
        perror("Error starting stream");
        close(fd);
        return 1;
    }

    while (keep_running) {
        if (capture_image(fd, "image.yuyv") == 0) {
            printf("Image captured: image.yuyv\n");
        } else {
            fprintf(stderr, "Failed to capture image.\n");
        }
        sleep(1);
    }

    if (ioctl(fd, VIDIOC_STREAMOFF, &buf.type) < 0) {
        perror("Error stopping stream");
    }

    if (ioctl(fd, VIDIOC_CQBUF, &buf) < 0) {
        perror("Error querying CBQ");
    }

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing CBQ");
    }

    if (ioctl(fd, VIDIOC_STREAMOFF, &buf.type) < 0) {
        perror("Error stopping stream");
    }

    close(fd);
    printf("Exiting cleanly.\n");
    return 0;
}

