#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define UART_PORT "/dev/ttyS0" // Or /dev/ttyAMA0
#define BAUD_RATE B115200
#define MAX_BUFFER 256

int serial_fd = -1; // Global serial file descriptor

// Signal handler for Ctrl+C
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        if (serial_fd != -1) {
            close(serial_fd);
        }
        exit(0);
    }
}

// Function to initialize the UART port
int init_uart(const char *port) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        perror("Error opening UART port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;  // 8N1, no parity
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0; // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read doesn't block
    tty.c_cc[VTIME] = 5; // 0.5 seconds read timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read data from the UART port
int read_uart_data(int fd, char *buffer, int max_len) {
    ssize_t bytes_read = read(fd, buffer, max_len - 1);
    if (bytes_read == -1) {
        if (errno == EAGAIN || errno == EWOULDBLOCK) {
            // No data available, return 0
            return 0;
        }
        perror("Error reading from UART");
        return -1;
    } else if (bytes_read > 0) {
        buffer[bytes_read] = '\0'; // Null-terminate the buffer
        return bytes_read;
    } else {
        return -1; // No data available
    }
}

// Function to process the received data (simple checksum validation)
int process_data(const char *data) {
    // In a real application, this function would perform checksum validation
    // and other data processing.
    // For this example, we just print the data.
    printf("Received: %s\n", data);
    return 0; // Indicate success
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize UART port
    serial_fd = init_uart(UART_PORT);
    if (serial_fd == -1) {
        return 1;
    }

    char buffer[MAX_BUFFER];
    int bytes_read;

    printf("UART program running. Press Ctrl+C to exit.\n");

    while (1) {
        bytes_read = read_uart_data(serial_fd, buffer, MAX_BUFFER);
        if (bytes_read > 0) {
            process_data(buffer);
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from UART, exiting.\n");
            break;
        }
        usleep(100000); // 100ms delay
    }

    // Close the serial port
    if (serial_fd != -1) {
        close(serial_fd);
    }

    return 0;
}

