// Define the number of MCP3008 channels
#define NUM_CHANNELS 3

// Define the SPI speed
#define SPI_SPEED 1000000 // 1 MHz

// Define the delay between readings (in milliseconds)
#define READ_DELAY_MS 5000

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        printf("\nExiting program...\n");
    }
}

// Function to read the DHT22 data line using libgpiod
int read_dht22_data_line() {
    int fd;
    char buf[2];

    // Open the GPIO pin for reading
    fd = open("/sys/class/gpio/gpio4/value", O_RDONLY);
    if (fd < 0) {
        perror("Error opening GPIO value file");
        return -1;
    }

    // Read the value from the GPIO pin
    if (read(fd, buf, 2) < 0) {
        perror("Error reading GPIO value");
        close(fd);
        return -1;
    }

    close(fd);

    // Return the value read from the GPIO pin
    return (buf[0] == 0) ? 1 : 0;
}

// Function to read the MCP3008 channel using SPI
int read_mcp3008_channel(int channel) {
    int fd;
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer tr;

    // Open the SPI device
    fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure the SPI transfer
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx_buf;
    tr.rx_buf = (unsigned long)rx_buf;
    tr.len = 3;
    tr.delay_usecs = 0;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = 8;

    // Construct the SPI message to send to the MCP3008
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    // Perform the SPI transfer
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Error performing SPI transfer");
        close(fd);
        return -1;
    }

    // Close the SPI device
    close(fd);

    // Return the value read from the MCP3008 channel
    return ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
}

// Function to read the DHT22 sensor data
int read_dht22_sensor(int gpio_pin, int spi_channel) {
    int data_line_value = read_dht22_data_line();
    if (data_line_value == -1) {
        fprintf(stderr, "Error reading DHT22 data line\n");
        return -1;
    }

    int mcp3008_values[NUM_CHANNELS];
    for (int i = 0; i < NUM_CHANNELS; i++) {
        int channel = i; // MCP3008 channel number
        mcp3008_values[i] = read_mcp3008_channel(channel);
        if (mcp3008_values[i] == -1) {
            fprintf(stderr, "Error reading MCP3008 channel %d\n", channel);
            return -1;
        }
    }

    // Combine the MCP3008 values into a single integer
    int sensor_data = (data_line_value << 16) | (mcp3008_values[0] << 8) | mcp3008_values[1];

    return sensor_data;
}

