#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 17

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int gpio_status;

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 17 as an output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Main loop
    while (program_running) {
        // Set GPIO 17 HIGH
        gpioWrite(GPIO_PIN, 1);
        gpio_status = gpioRead(GPIO_PIN);
        printf("GPIO %d HIGH, gpioRead returned %d\n", GPIO_PIN, gpio_status);

        // Wait for 1 second
        sleep(1);

        // Set GPIO 17 LOW
        gpioWrite(GPIO_PIN, 0);
        gpio_status = gpioRead(GPIO_PIN);
        printf("GPIO %d LOW, gpioRead returned %d\n", GPIO_PIN, gpio_status);

        // Wait for 1 second
        sleep(1);
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

