    gpio_status = gpioSetMode(GPIO_PIN, PI_OUTPUT);
    if (gpio_status != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output: %d\n", GPIO_PIN, gpio_status);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Set GPIO 4 HIGH
        gpio_status = gpioWrite(GPIO_PIN, 1);
        if (gpio_status != 0) {
            fprintf(stderr, "Failed to write HIGH to GPIO %d: %d\n", GPIO_PIN, gpio_status);
            break; // Exit loop on write error
        }

        // Report the state to standard output
        printf("GPIO %d is HIGH\n", GPIO_PIN);

        // Wait for 2 seconds
        sleep(2);

        // Set GPIO 4 LOW
        gpio_status = gpioWrite(GPIO_PIN, 0);
        if (gpio_status != 0) {
            fprintf(stderr, "Failed to write LOW to GPIO %d: %d\n", GPIO_PIN, gpio_status);
