#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_FORMAT "YUYV"
#define IMAGE_BUFFER_COUNT 1

static volatile int keep_running = 1;

void int_handler(int dummy) {
    keep_running = 0;
}

int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    void *buffers[IMAGE_BUFFER_COUNT];
    unsigned int n_buffers;
    unsigned char *image_data;
    FILE *fp;
    struct timespec sleep_time;
    struct v4l2_streamparm streamparm;
    struct v4l2_requestbufs streamparm_req;
    struct v4l2_buffer streamparm_buf;
    unsigned int streamparm_buffers[IMAGE_BUFFER_COUNT];
    unsigned int streamparm_n_buffers[IMAGE_BUFFER_COUNT];
    unsigned int streamparm_index[IMAGE_BUFFER_COUNT];

    signal(SIGINT, int_handler);

    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening device");
        return 1;
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is no video capture device\n", DEVICE_NAME);
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", DEVICE_NAME);
        close(fd);
        return 1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(fd);
        return 1;
    }

    memset(&req, 0, sizeof(req));
    req.count = IMAGE_BUFFER_COUNT;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(fd);
        return 1;
    }

    memset(buffers, 0, sizeof(buffers));
    n_buffers = req.count;

    for (unsigned int i = 0; i < n_buffers; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("Error querying buffer");
            close(fd);
            return 1;
        }

        buffers[i] = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffers[i] == MAP_FAILED) {
            perror("Error mapping buffer");
            close(fd);
            return 1;
        }

        memset(&streamparm, 0, sizeof(streamparm));
        streamparm.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        streamparm.memory = V4L2_MEMORY_MMAP;
        streamparm.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Error queuing buffer");
            close(fd);
            return 1;
        }
    }

    memset(&streamparm_req, 0, sizeof(streamparm_req));
    streamparm_req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    streamparm_req.memory = V4L2_MEMORY_MMAP;
    streamparm_req.count = n_buffers;
    streamparm_req.index = 0;

    if (ioctl(fd, VIDIOC_STREAMON, &streamparm_req) < 0) {
        perror("Error starting streaming");
        close(fd);
        return 1;
    }

    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 100000000; // 0.1 seconds

    while (keep_running) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = 0;

        if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            perror("Error dequeuing buffer");
            break;
        }

        image_data = (unsigned char *)buffers[buf.index];
        fp = fopen("image.yuyv", "wb");
        fwrite(image_data, 1, IMAGE_WIDTH * IMAGE_HEIGHT * 2, fp);
        fclose(fp);

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Error queuing buffer");
            break;
        }
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_STREAMOFF, &streamparm_req) < 0) {
        perror("Error stopping streaming");
    }

    for (unsigned int i = 0; i < n_buffers; i++) {
        if (munmap(buffers[i], buf.length) < 0) {
            perror("Error unmapping buffer");
        }
    }

    close(fd);
    return 0;
}

