#include <string.h>

#define PCF8574_I2C_ADDR 0x48
#define PCF8574_DATA_PIN 0x40
#define PCF8574_ENABLE 0x4A

int main() {
    int i2c_fd;
    uint8_t buf[2];
    uint8_t data[2];
    int i;

    // Open I2C device
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, PCF8574_I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Enable the PCF8574
    buf[0] = PCF8574_ENABLE;
    buf[1] = 0x10; // Enable all 40 pins
    if (write(i2c_fd, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        close(i2c_fd);
        return 1;
    }
    usleep(100000); // Wait for the PCF8574 to be ready

    // Read data from the PCF8574
    for (i = 0; i < 2; i++) {
        buf[0] = PCF8574_DATA_PIN;
        if (write(i2c_fd, buf, 1) != 1) {
            perror("Failed to write to I2C device");
            close(i2c_fd);
            return 1;
        }
        if (read(i2c_fd, data, 1) != 1) {
            perror("Failed to read from I2C device");
            close(i2c_fd);
            return 1;
        }
        printf("Data %d: %d\n", i + 1, data[0]);
    }

    // Disable the PCF8574
    buf[0] = PCF8574_ENABLE;
    buf[1] = 0x00; // Disable all 40 pins
    if (write(i2c_fd, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        close(i2c_fd);
        return 1;
    }
    usleep(100000); // Wait for the PCF8574 to be ready

    close(i2c_fd);
    return 0;
}

