        gpioWrite(TRIGGER_PIN, 0);

        uint32_t start_tick = gpioTick();
        uint32_t end_tick = start_tick;

        // Wait for echo to go high (with timeout)
        int timeout = 10000; // 10ms timeout
        while (gpioRead(ECHO_PIN) == 0 && timeout > 0) {
            timeout--;
            gpioDelay(1); // Check every 1 us
        }

        if (timeout <= 0) {
            fprintf(stderr, "Timeout waiting for echo high\n");
            gpioTerminate();
            return 1;
        }

        start_tick = gpioTick();

        // Wait for echo to go low (with timeout)
        timeout = 10000; // 10ms timeout
        while (gpioRead(ECHO_PIN) == 1 && timeout > 0) {
            timeout--;
            gpioDelay(1); // Check every 1 us
        }

        if (timeout <= 0) {
            fprintf(stderr, "Timeout waiting for echo low\n");
            gpioTerminate();
            return 1;
        }

        end_tick = gpioTick();

        uint32_t diff = end_tick - start_tick;

        // Calculate distance in centimeters (speed of sound: 343 m/s)
        float distance = (float)diff / 2.0 / 29.1;

        printf("Distance: %.2f cm\n", distance);

        gpioDelay(500); // Delay between measurements
    }

    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 23
#define DEBOUNCE_DELAY_MS 50

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int gpio_status;
    int current_state = 0;
    int previous_state = 0;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 23 as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Set initial state to LOW
    gpioWrite(GPIO_PIN, 0);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("GPIO control program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read GPIO state
        gpio_status = gpioRead(GPIO_PIN);

        // Debounce and state change detection
        if (gpio_status != previous_state) {
            if (gpio_status == 1) {
                current_state = 1;
            } else {
                current_state = 0;
            }

            // Report the current state
            printf("Current state: %d\n", current_state);

            // Wait for a short period
            gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Convert ms to microseconds
        }

        previous_state = gpio_status;
        gpioDelay(1000); // Check every 1ms
    }

    // Clean up and exit
    gpioWrite(GPIO_PIN, 0); // Set to LOW before exiting
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

