#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B

int i2c_fd;

int main() {
    const char *i2c_device = "/dev/i2c-1";
    int16_t accel_x, accel_y, accel_z;
    int ret;

    // Open I2C device
    if ((i2c_fd = open(i2c_device, O_RDWR)) < 0) {
        perror("Error opening I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Wake up the MPU6050
    ret = write(i2c_fd, &PWR_MGMT_1, 1);
    if (ret < 0) {
        perror("Error writing to PWR_MGMT_1");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        // Read accelerometer data
        ret = read(i2c_fd, &accel_x, 1);
        if (ret < 0) {
            perror("Error reading ACCEL_XOUT_H");
            close(i2c_fd);
            return 1;
        }

        ret = read(i2c_fd, &accel_y, 1);
        if (ret < 0) {
            perror("Error reading ACCEL_YOUT_H");
            close(i2c_fd);
            return 1;
        }

        ret = read(i2c_fd, &accel_z, 1);
        if (ret < 0) {
            perror("Error reading ACCEL_ZOUT_H");
            close(i2c_fd);
            return 1;
        }

        // Print the readings
        printf("Accelerometer X: %d, Y: %d, Z: %d\n", accel_x, accel_y, accel_z);

        // Wait 0.1 seconds
        usleep(100000);
    }

    close(i2c_fd);
    return 0;
}

