#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <errno.h>
#include <string.h>

#define SHT31_ADDR 0x44
#define MEASURE_CMD 0x2C06 // High repeatability, clock stretching disabled

int i2c_fd;

// Function to calculate CRC8 checksum
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    uint8_t data[6];
    uint16_t temperature, humidity;
    int result;

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SHT31_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        // Send measurement command
        uint8_t cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
        result = write(i2c_fd, cmd, 2);
        if (result != 2) {
            fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
            close(i2c_fd);
            return EXIT_FAILURE;
        }

        // Wait for measurement (typical 10ms, but let's wait 20ms)
        usleep(20000);

        // Read 6 bytes of data
        result = read(i2c_fd, data, 6);
        if (result != 6) {
            fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
            close(i2c_fd);
            return EXIT_FAILURE;
        }

        // CRC Check
        if (crc8(data, 2) != data[2] || crc8(data + 3, 2) != data[5]) {
            fprintf(stderr, "CRC check failed\n");
            close(i2c_fd);
            return EXIT_FAILURE;
        }

        // Convert data
        temperature = (data[0] << 8) | data[1];
        humidity = (data[3] << 8) | data[4];

        // Print temperature and humidity
        printf("Temperature: %d C, Humidity: %d %%\n", temperature, humidity);

        // Wait 5 seconds
        sleep(5);
    }

    close(i2c_fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <string.h>

#define NUM_GPIOS 10

int main(int argc, char *argv[]) {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[NUM_GPIOS];
    int i;
    int ret;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <chip_name>\n", argv[0]);
        return EXIT_FAILURE;
    }

    char *chip_name = argv[1];

    chip = gpiod_chip_open_by_name(chip_name);
    if (!chip) {
        fprintf(stderr, "Error opening chip '%s': %s\n", chip_name, gpiod_strerror(chip->error));
        return EXIT_FAILURE;
    }

    for (i = 0; i < NUM_GPIOS; i++) {
        lines[i] = gpiod_chip_get_line(chip, i);
        if (!lines[i]) {
            fprintf(stderr, "Error getting line %d: %s\n", i, gpiod_strerror(lines[i]->error));
            goto cleanup;
        }

        ret = gpiod_line_request_output(lines[i], NULL, GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
        if (ret < 0) {
            fprintf(stderr, "Error requesting line %d as output: %s\n", i, gpiod_strerror(ret));
            goto cleanup;
        }
    }

    for (i = 0; i < NUM_GPIOS; i++) {
        ret = gpiod_line_set_value(lines[i], 1);
        if (ret < 0) {
            fprintf(stderr, "Error setting value for line %d: %s\n", i, gpiod_strerror(ret));
            goto cleanup;
        }
        printf("GPIO %d: %d\n", i, ret);
    }

cleanup:
    for (i = 0; i < NUM_GPIOS; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

