#define GPIO_2_PATH "/sys/class/gpio/gpio2/value"
#define GPIO_3_PATH "/sys/class/gpio/gpio3/value"
#define GPIO_17_PATH "/sys/class/gpio/gpio17/value"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *gpio2_line = NULL;
static struct gpiod_line *gpio3_line = NULL;
static struct gpiod_line *gpio17_line = NULL;

static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    struct gpiod_line_request_config config;
    struct gpiod_line_request_update update;
    struct timespec sleep_time;
    int current_value;
    int previous_value = -1; // Initialize to an invalid value

    // Register signal handler for graceful exit
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    gpio2_line = gpiod_chip_get_line(chip, 2);
    gpio3_line = gpiod_chip_get_line(chip, 3);
    gpio17_line = gpiod_chip_get_line(chip, 17);

    if (!gpio2_line || !gpio3_line || !gpio17_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    config.consumer = "gpio_control";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(gpio2_line, &config, 0) < 0) {
        perror("Error requesting GPIO 2");
        gpiod_line_release(gpio2_line);
        gpiod_line_release(gpio3_line);
        gpiod_line_release(gpio17_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request(gpio3_line, &config, 0) < 0) {
        perror("Error requesting GPIO 3");
        gpiod_line_release(gpio2_line);
        gpiod_line_release(gpio17_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request(gpio17_line, &config, 0) < 0) {
        perror("Error requesting GPIO 17");
        gpiod_line_release(gpio2_line);
        gpiod_line_release(gpio3_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (!terminate) {
        current_value = gpiod_line_get_value(gpio2_line);

        if (current_value < 0) {
            perror("Error reading GPIO 2 value");
            break;
        }

        if (current_value != previous_value) {
            printf("GPIO 2: %d\n", current_value);
            previous_value = current_value;
        }

        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 100000000; // 100ms
        nanosleep(&sleep_time, NULL);

