        fprintf(stderr, "Error opening %s: %s\n", w1_slave_path, strerror(errno));
        return -1;
    }

    char buffer[256];
    ssize_t bytes_read = read(fd, buffer, sizeof(buffer) - 1);
    close(fd);

    if (bytes_read < 0) {
        fprintf(stderr, "Error reading from %s: %s\n", w1_slave_path, strerror(errno));
        return -1;
    }
    buffer[bytes_read] = '\0';

    if (strstr(buffer, "YES") == NULL) {
        fprintf(stderr, "CRC check failed for device %s\n", device_id);
        return -1;
    }

    char *temp_str = strstr(buffer, "t=");
    if (temp_str == NULL) {
        fprintf(stderr, "Temperature data not found for device %s\n", device_id);
        return -1;
    }

    long temperature_milli_celsius = strtol(temp_str + 2, NULL, 10);
    return (int)(temperature_milli_celsius / 1000.0);
}

