void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        // Rising edge
        gpioSetTimerFuncEx(ECHO_PIN, 0, 0, NULL); // Disable further callbacks on this pin
    } else if (level == 0) {
        // Falling edge
        uint32_t start = tick;
        gpioSetTimerFuncEx(ECHO_PIN, 0, 0, NULL); // Disable further callbacks on this pin

        // Wait for the rising edge
        while (gpioRead(ECHO_PIN) == 0) {
            if (terminate) return;
        }
        uint32_t end = tick;

        uint32_t diff = end - start;
        double time_taken = (double)diff / 1000000.0; // Time in seconds

        if (time_taken > 0.0) {
            printf("Time: %.3f seconds\n", time_taken);
        } else {
            printf("Invalid time measurement\n");
        }
    }
}

