static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line17 = NULL;
static struct gpiod_line *line23 = NULL;
static struct gpiod_line *line24 = NULL;

static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int ret;
    struct gpiod_line_request_config config;
    struct gpiod_line_request req;
    struct gpiod_line_value_input_s value;

    // Register signal handler for graceful exit
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    // Get line handles
    line17 = gpiod_chip_get_line(chip, GPIO_17);
    line23 = gpiod_chip_get_line(chip, GPIO_23);
