    if (!line17 || !line23 || !line24) {
        fprintf(stderr, "Error getting line '%d': %s\n", GPIO_17, strerror(errno));
        fprintf(stderr, "Error getting line '%d': %s\n", GPIO_23, strerror(errno));
        fprintf(stderr, "Error getting line '%d': %s\n", GPIO_24, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO lines for output
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio_control";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(line17, &req, &config) < 0) {
        fprintf(stderr, "Error requesting GPIO %d for output: %s\n", GPIO_17, strerror(errno));
        gpiod_line_release(line17);
        gpiod_line_release(line23);
