        gpiod_line_release(line17);
        gpiod_line_release(line23);
        gpiod_line_release(line24);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request(line24, &req, &config) < 0) {
        fprintf(stderr, "Error requesting GPIO %d for output: %s\n", GPIO_24, strerror(errno));
        gpiod_line_release(line17);
        gpiod_line_release(line23);
        gpiod_line_release(line24);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        // Set GPIO 17 to HIGH
        if (gpiod_line_set_value(line17, 1) < 0) {
            fprintf(stderr, "Error setting GPIO %d to HIGH: %s\n", GPIO_17, strerror(errno));
            break;
        }

        // Set GPIO 23 to LOW
        if (gpiod_line_set_value(line23, 0) < 0) {
            fprintf(stderr, "Error setting GPIO %d to LOW: %s\n", GPIO_23, strerror(errno));
            break;
        }

        // Set GPIO 24 to LOW
