            fprintf(stderr, "Error setting GPIO %d to LOW: %s\n", GPIO_24, strerror(errno));
            break;
        }

        // Read GPIO 17 value
        value.consumer = "gpio_control";
        value.request_type = GPIOD_LINE_VALUE_INPUT;
        value.value.value = 0; // Initialize value

        if (gpiod_line_request_output(line17, &value, 1) < 0) {
            fprintf(stderr, "Error requesting GPIO %d for output: %s\n", GPIO_17, strerror(errno));
            break;
        }

        if (gpiod_line_request_output(line17, &value, 0) < 0) {
            fprintf(stderr, "Error requesting GPIO %d for output: %s\n", GPIO_17, strerror(errno));
            break;
        }

        if (gpiod_line_request_output(line17, &value, 1) < 0) {
            fprintf(stderr, "Error requesting GPIO %d for output: %s\n", GPIO_17, strerror(errno));
            break;
        }

        if (gpiod_line_request_output(line17, &value, 0) < 0) {
            fprintf(stderr, "Error requesting GPIO %d for output: %s\n", GPIO_17, strerror(errno));
            break;
        }

        if (gpiod_line_release(line17) < 0) {
            fprintf(stderr, "Error releasing GPIO %d: %s\n", GPIO_17, strerror(errno));
            break;
        }

        // Read GPIO 23 value
        value.consumer = "gpio_control";
        value.request_type = GPIOD_LINE_VALUE_INPUT;
        value.value.value = 0; // Initialize value

        if (gpiod_line_request_output(line23, &value, 1) < 0) {
            fprintf(stderr, "Error requesting GPIO %d for output: %s\n", GPIO_23, strerror(errno));
            break;
        }

        if (gpiod_line_release(line23) < 0) {
            fprintf(stderr, "Error releasing GPIO %d: %s\n", GPIO_23, strerror(errno));
            break;
        }

        // Read GPIO 24 value
        value.consumer = "gpio_control";
        value.request_type = GPIOD_LINE_VALUE_INPUT;
        value.value.value = 0; // Initialize value

        if (gpiod_line_request_output(line24, &value, 1) < 0) {
            fprintf(stderr, "Error requesting GPIO %d for output: %s\n", GPIO_24, strerror(errno));
            break;
        }

        if (gpiod_line_release(line24) < 0) {
            fprintf(stderr, "Error releasing GPIO %d: %s\n", GPIO_24, strerror(errno));
            break;
        }

        // Print GPIO values
        printf("GPIO 17: %d, GPIO 23: %d, GPIO 24: %d\n", value.value.value, value.value.value, value.value.value);

        sleep(1);
    }

    // Clean up
    if (line17) gpiod_line_release(line17);
    if (line23) gpiod_line_release(line23);
    if (line24) gpiod_line_release(line24);
    if (chip) gpiod_chip_close(chip);

    return EXIT_SUCCESS;
