#define PWM_GPIO 4
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PWM_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);

    signal(SIGINT, signal_handler);

    while (!terminate) {
        int duty_cycle = rand() % 1024; // Generate a random duty cycle between 0 and 1023
        int valid_duty_cycle = 0;

        if (duty_cycle >= 0 && duty_cycle <= 1023) {
            valid_duty_cycle = duty_cycle;
        } else {
            fprintf(stderr, "Invalid duty cycle: %d\n", duty_cycle);
        }

        if (valid_duty_cycle != 0) {
            gpioPWM(PWM_GPIO, valid_duty_cycle);
            printf("Duty Cycle: %d\n", valid_duty_cycle);
        } else {
            fprintf(stderr, "Skipping PWM due to invalid duty cycle.\n");
        }

        gpioDelay(100000); // 0.1 seconds
    }

    gpioPWM(PWM_GPIO, 0); // Stop PWM
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return 0;
}

