#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define DHT22_GPIO 4
#define MAX_RETRIES 3

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int read_dht22(int gpio, int *data) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        // Set GPIO as output
        gpioSetMode(gpio, PI_OUTPUT);
        gpioWrite(gpio, 0);
        gpioDelay(1); // 1ms
        gpioWrite(gpio, 1);
        gpioDelay(40); // 40us

        // Set GPIO as input
        gpioSetMode(gpio, PI_INPUT);

        // Wait for response (low for 80us, then high for 80us)
        int timeout = 0;
        while (gpioRead(gpio) == 1) {
            timeout++;
            if (timeout > 100) {
                fprintf(stderr, "DHT22 timeout waiting for start signal (GPIO %d)\n", gpio);
                return -1; // Timeout
            }
            gpioDelay(1); // 1us
        }

        timeout = 0;
        while (gpioRead(gpio) == 0) {
            timeout++;
            if (timeout > 100) {
                fprintf(stderr, "DHT22 timeout waiting for end of start signal (GPIO %d)\n", gpio);
                return -1; // Timeout
            }
            gpioDelay(1); // 1us
        }

        timeout = 0;
        while (gpioRead(gpio) == 1) {
            timeout++;
            if (timeout > 100) {
                fprintf(stderr, "DHT22 timeout waiting for end of data signal (GPIO %d)\n", gpio);
                return -1; // Timeout
            }
            gpioDelay(1); // 1us
        }

        // Read 40 bits (5 bytes)
        for (int i = 0; i < 5; i++) {
            for (int j = 0; j < 8; j++) {
                timeout = 0;
                while (gpioRead(gpio) == 0) {
                    timeout++;
                    if (timeout > 100) {
                        fprintf(stderr, "DHT22 timeout waiting for bit start (GPIO %d)\n", gpio);
                        return -1; // Timeout
                    }
                    gpioDelay(1); // 1us
                }

                timeout = 0;
                while (gpioRead(gpio) == 1) {
                    timeout++;
                    if (timeout > 100) {
                        fprintf(stderr, "DHT22 timeout waiting for bit end (GPIO %d)\n", gpio);
                        return -1; // Timeout
                    }
                    gpioDelay(1); // 1us
                }

                if (timeout > 100) {
                    fprintf(stderr, "DHT22 timeout reading bit %d (GPIO %d)\n", j, gpio);
                    return -1; // Timeout
                }

                data[i] <<= 1;
                if (timeout > 100) {
                    fprintf(stderr, "DHT22 timeout reading bit %d (GPIO %d)\n", j, gpio);
                    return -1; // Timeout
                }
                if (gpioRead(gpio) == 1) {
                    data[i] |= 1;
                }
            }
        }

        // Validate checksum
        if ((data[0] + data[1] + data[2] + data[3]) & 0xFF != data[4]) {
            fprintf(stderr, "DHT22 checksum error (GPIO %d)\n", gpio);
            return -1; // Checksum error
        }

        return 0; // Success
    }

    fprintf(stderr, "DHT22 read failed after %d retries (GPIO %d)\n", MAX_RETRIES, gpio);
    return -1; // All retries failed
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    int data[5];
    int valid_readings[MAX_RETRIES];
    int valid_count = 0;

    while (!terminate) {
        int retries = 0;
        int result = -1;

        while (retries < MAX_RETRIES) {
            result = read_dht22(DHT22_GPIO, data);
            if (result == 0) {
                valid_readings[retries] = data[0];
                valid_count++;
                break;
            } else {
                fprintf(stderr, "DHT22 read failed, retrying (GPIO %d, attempt %d)\n", DHT22_GPIO, retries + 1);
                retries++;
                gpioDelay(100); // 100ms delay
            }
        }

        if (valid_count == 0) {
            fprintf(stderr, "DHT22 read failed after %d attempts (GPIO %d)\n", MAX_RETRIES, DHT22_GPIO);
        } else {
            // Calculate average
            int sum = 0;
            for (int i = 0; i < MAX_RETRIES; i++) {
                sum += valid_readings[i];
            }
            int average = sum / MAX_RETRIES;

            printf("Average DHT22 reading: %d\n", average);
        }

        gpioDelay(5000); // 5 seconds delay
    }

    gpioTerminate();
    return 0;
}

