#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define RETRY_DELAY_SEC 60

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int read_dht22(int gpio, float *temperature, float *humidity) {
    int i;
    int data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;
    int byte_index = 0;

    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(1);
    gpioWrite(gpio, 1);
    gpioDelay(30); // Changed from 40 to 30
    gpioSetMode(gpio, PI_INPUT);

    // Wait for the DHT22 to pull the line low
    int timeout = 0;
    while (gpioRead(gpio) == 1 && timeout < 100) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout++;
    }

    if (timeout >= 100) {
        fprintf(stderr, "DHT22: Timeout waiting for start signal (GPIO %d)\n", gpio);
        return -1; // Timeout error
    }

    timeout = 0;
    while (gpioRead(gpio) == 0 && timeout < 100) {
        gpioDelay(1);
        timeout++;
    }

    if (timeout >= 100) {
        fprintf(stderr, "DHT22: Timeout waiting for start signal (GPIO %d, bit 0)\n", gpio);
        return -1; // Timeout error
    }

    timeout = 0;
    while (gpioRead(gpio) == 1 && timeout < 100) {
        gpioDelay(1);
        timeout++;
    }

    if (timeout >= 100) {
        fprintf(stderr, "DHT22: Timeout waiting for start signal (GPIO %d, bit 1)\n", gpio);
        return -1; // Timeout error
    }

    timeout = 0;
    while (gpioRead(gpio) == 0 && timeout < 100) {
        gpioDelay(1);
        timeout++;
    }

    if (timeout >= 100) {
        fprintf(stderr, "DHT22: Timeout waiting for start signal (GPIO %d, bit 2)\n", gpio);
        return -1; // Timeout error
    }

    timeout = 0;
    while (gpioRead(gpio) == 1 && timeout < 100) {
        gpioDelay(1);
        timeout++;
    }

    if (timeout >= 100) {
        fprintf(stderr, "DHT22: Timeout waiting for start signal (GPIO %d, bit 3)\n", gpio);
        return -1; // Timeout error
    }

    timeout = 0;
    while (gpioRead(gpio) == 0 && timeout < 100) {
        gpioDelay(1);
        timeout++;
    }

    if (timeout >= 100) {
        fprintf(stderr, "DHT22: Timeout waiting for start signal (GPIO %d, bit 4)\n", gpio);
        return -1; // Timeout error
    }

    // Read 40 bits (5 bytes)
    for (i = 0; i < 40; i++) {
        timeout = 0;
        while (gpioRead(gpio) == 0 && timeout < 100) {
            gpioDelay(1);
            timeout++;
        }

        if (timeout >= 100) {
            fprintf(stderr, "DHT22: Timeout waiting for bit %d (GPIO %d)\n", i, gpio);
            return -1; // Timeout error
        }

        long start = gpioTick();
        timeout = 0;
        while (gpioRead(gpio) == 1 && timeout < 100) {
            gpioDelay(1);
            timeout++;
        }
        long end = gpioTick();

        if ((end - start) > 40) {
            data[byte_index] |= (1 << (7 - bit_count));
        }

        bit_count++;
        if (bit_count == 8) {
            bit_count = 0;
            byte_index++;
        }
    }

    // Checksum validation
    if ((data[0] + data[1] + data[2] + data[3]) != data[4]) {
        fprintf(stderr, "DHT22: Checksum error (GPIO %d)\n", gpio);
        return -1; // Checksum error
    }

    *humidity = (float)((data[0] << 8) + data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80) {
        *temperature = -*temperature;
    }

    return 0;
}

