    while (!terminate) {
        retries = 0;
        result = -1; // Initialize to error

        while (retries < MAX_RETRIES && result != 0) {
            result = read_dht22(DHT22_GPIO, &temperature, &humidity);
            if (result == 0) {
                printf("Temperature: %.1f°C, Humidity: %.1f%%\n", temperature, humidity);
            } else {
                fprintf(stderr, "DHT22 read failed (GPIO %d). Retry %d/%d\n", DHT22_GPIO, retries + 1, MAX_RETRIES);
            }
            retries++;
            gpioDelay(RETRY_DELAY_SEC);
        }

        if (result != 0) {
            fprintf(stderr, "DHT22 read failed after %d retries. Giving up.\n", MAX_RETRIES);
        }

        gpioDelay(5000); // Wait 5 seconds before next reading
    }

