    int gpio_16_state = 0;
    int gpio_20_state = 0;
    int pigpio_init_result;

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    pigpio_init_result = gpioInitialise();
    if (pigpio_init_result < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", pigpio_init_result);
        return 1;
    }

    // Set GPIO 16 as output
    gpioSetMode(GPIO_16, PI_OUTPUT);
    gpio_16_state = 0; // Initialize to LOW

    // Set GPIO 20 as output
    gpioSetMode(GPIO_20, PI_OUTPUT);
    gpio_20_state = 0; // Initialize to LOW

    printf("GPIO control program started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Set GPIO 16 state
        gpioWrite(GPIO_16, gpio_16_state);
        gpio_16_state = !gpio_16_state; // Toggle the state

        // Set GPIO 20 state
        gpioWrite(GPIO_20, gpio_20_state);
        gpio_20_state = !gpio_20_state; // Toggle the state

        // Print the current state of both GPIOs
        printf("GPIO 16: %d, GPIO 20: %d\n", gpio_16_state, gpio_20_state);

        // Wait for 0.1 seconds
        usleep(100000); // 100 ms
    }

