#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 17

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        // Rising edge
        gpioSetTimerFuncEx(ECHO_PIN, 0, 0, NULL); // Disable further callbacks on this pin
    } else if (level == 0) {
        // Falling edge
        uint32_t start = tick;
        gpioSetTimerFuncEx(ECHO_PIN, 0, 0, NULL); // Disable further callbacks on this pin
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(2);
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);

    gpioSetTimerFuncEx(ECHO_PIN, 50, 0, echo_callback); // 50ms timeout

    signal(SIGINT, signal_handler);

    while (!terminate) {
        gpioDelay(100);
    }

    gpioSetTimerFuncEx(ECHO_PIN, 0, 0, NULL); // Disable callback

    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 18

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int ret;
    struct gpiod_line_request_config config;

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    ret = gpiod_chip_open(GPIO_CHIP, &chip);
    if (ret < 0) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(-ret));
        return EXIT_FAILURE;
    }

    // Get GPIO line
    ret = gpiod_chip_get_line(chip, GPIO_PIN, &line);
    if (ret < 0) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN, strerror(-ret));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure GPIO line as output
    memset(&config, 0, sizeof(config));
    config.consumer = "my_gpio_consumer";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d: %s\n", GPIO_PIN, strerror(-ret));
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error getting GPIO line value: %s\n", strerror(-value));
            break;
        }

        printf("GPIO %d: %d\n", GPIO_PIN, value);
        usleep(100000); // 100ms
    }

    // Clean up
    printf("Cleaning up...\n");
    gpiod_line_set_value(line, 0); // Set to low before exiting
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define BMP280_ADDR 0x76
#define BMP280_CHIP_ID_REG 0xD0
#define BMP280_TEMP_MSB_REG 0xFA
#define BMP280_PRESS_MSB_REG 0xF7

int main() {
    int file;
    int bmp280_address = BMP280_ADDR;
    int chip_id;
    int32_t temperature, pressure;
    int retries = 3;

    // Open I2C bus
    if ((file = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set slave address
    if (ioctl(file, I2C_SLAVE, bmp280_address) < 0) {
        perror("Failed to set I2C slave address");
        close(file);
        return 1;
    }

    // Check if the device is present
    if (ioctl(file, I2C_SLAVE, BMP280_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(file);
        return 1;
    }

    // Read chip ID
    uint8_t chip_id_reg = BMP280_CHIP_ID_REG;
    uint8_t chip_id_val[2];
    int retries_chip_id = 3;
    while (retries_chip_id > 0) {
        if (write(file, &chip_id_reg, 1) != 1) {
            perror("Failed to write to I2C device");
            close(file);
            return 1;
        }
        if (read(file, chip_id_val, 2) == 2) {
            chip_id = (chip_id_val[0] << 8) | chip_id_val[1];
            if (chip_id == 0x58) {
                break;
            } else {
                fprintf(stderr, "Incorrect chip ID: 0x%02X\n", chip_id);
                retries_chip_id--;
                usleep(100000); // Wait 100ms before retry
            }
        } else {
            perror("Failed to read from I2C device");
            close(file);
            return 1;
        }
    }
    if (retries_chip_id == 0) {
        fprintf(stderr, "BMP280 not found at address 0x%02X\n", bmp280_address);
        close(file);
        return 1;
    }

    // Read temperature and pressure
    uint8_t temp_msb_reg = BMP280_TEMP_MSB_REG;
    uint8_t temp_lsb_reg = BMP280_TEMP_MSB_REG + 1;
    uint8_t temp_xlsb_reg = BMP280_TEMP_MSB_REG + 2;
    uint8_t press_msb_reg = BMP280_PRESS_MSB_REG;
    uint8_t press_lsb_reg = BMP280_PRESS_MSB_REG + 1;
    uint8_t press_xlsb_reg = BMP280_PRESS_MSB_REG + 2;

    int retries_read = 3;
    while (retries_read > 0) {
        if (write(file, &temp_msb_reg, 1) != 1) {
            perror("Failed to write to I2C device");
            close(file);
            return 1;
        }
        if (read(file, &temp_msb_reg, 1) != 1) {
            perror("Failed to read from I2C device");
            close(file);
            return 1;
        }

        if (write(file, &temp_lsb_reg, 1) != 1) {
            perror("Failed to write to I2C device");
            close(file);
            return 1;
        }
        if (read(file, &temp_lsb_reg, 1) != 1) {
            perror("Failed to read from I2C device");
            close(file);
            return 1;
        }

        if (write(file, &temp_xlsb_reg, 1) != 1) {
            perror("Failed to write to I2C device");
            close(file);
            return 1;
        }
        if (read(file, &temp_xlsb_reg, 1) != 1) {
            perror("Failed to read from I2C device");
            close(file);
            return 1;
        }

        if (write(file, &press_msb_reg, 1) != 1) {
            perror("Failed to write to I2C device");
            close(file);
            return 1;
        }
        if (read(file, &press_msb_reg, 1) != 1) {
            perror("Failed to read from I2C device");
            close(file);
            return 1;
        }

        if (write(file, &press_lsb_reg, 1) != 1) {
            perror("Failed to write to I2C device");
            close(file);
            return 1;
        }
        if (read(file, &press_lsb_reg, 1) != 1) {
            perror("Failed to read from I2C device");
            close(file);
            return 1;
        }

        if (write(file, &press_xlsb_reg, 1) != 1) {
            perror("Failed to write to I2C device");
            close(file);
            return 1;
        }
        if (read(file, &press_xlsb_reg, 1) != 1) {
            perror("Failed to read from I2C device");
            close(file);
            return 1;
        }

        uint8_t temp_data[3];
        uint8_t press_data[3];

        if (read(file, temp_data, 3) != 3) {
            perror("Failed to read temperature data");
            close(file);
            return 1;
        }

        if (read(file, press_data, 3) != 3) {
            perror("Failed to read pressure data");
            close(file);
            return 1;
        }

        temperature = (temp_data[0] << 12) | (temp_data[1] << 4) | (temp_data[2] >> 4);
        pressure = (press_data[0] << 12) | (press_data[1] << 4) | (press_data[2] >> 4);

        printf("Temperature: %d\n", temperature);
        printf("Pressure: %d\n", pressure);

        retries_read--;
        usleep(100000); // Wait 100ms before retry
    }

    close(file);
    return 0;
}

