// Function to initialize the UART port
int init_uart(const char *port) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        perror("Error opening UART port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;  // 8N1, no parity
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0; // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read doesn't block
    tty.c_cc[VTIME] = TIMEOUT_SEC; // Timeout of 1 second

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read data from the UART port
int read_uart_data(int fd, char *buffer, int size) {
    ssize_t bytes_read = read(fd, buffer, size);
    if (bytes_read == -1) {
        if (errno == EAGAIN || errno == EWOULDBLOCK) {
            // Timeout occurred
            return 0; // No data read
        } else {
            perror("Error reading from UART");
            return -1;
        }
    } else if (bytes_read == 0) {
        // No data available
        return 0;
    } else {
        // Data read successfully
        return bytes_read;
    }
}

// Function to print the received data
void print_data(const char *data) {
    printf("Received: %s\n", data);
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize UART
    serial_fd = init_uart(UART_PORT);
    if (serial_fd == -1) {
        fprintf(stderr, "UART initialization failed. Exiting.\n");
        return 1;
    }

    char buffer[READ_SIZE];
    int bytes_read;

    while (1) {
        // Read data from UART
        bytes_read = read_uart_data(serial_fd, buffer, READ_SIZE);
        if (bytes_read > 0) {
            // Print the received data
            print_data(buffer);
        } else if (bytes_read < 0) {
            // Error occurred, print error message
            fprintf(stderr, "Error reading from UART. Exiting.\n");
            close(serial_fd);
            return 1;
        }

        // Wait for 0.1 seconds
        struct timespec req = {0};
        req.tv_sec = 0;
        req.tv_nsec = 100000000; // 0.1 seconds
        nanosleep(&req, NULL);
    }

    // This point should not be reached due to the signal handler
    close(serial_fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int read_pulse_width() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    int start = gpioTick();
    while (gpioRead(ECHO_PIN) == 0 && (gpioTick() - start) < 100000) {}
    int echo_start = gpioTick();

    while (gpioRead(ECHO_PIN) == 1 && (gpioTick() - echo_start) < 100000) {}
    int echo_end = gpioTick();

    int pulse_width = echo_end - echo_start;
    if (pulse_width < 0) {
        pulse_width += 0xFFFFFFFF; // Handle tick rollover
    }
    return pulse_width;
}

int validate_pulse_width(int pulse_width) {
    return (pulse_width > 2 && pulse_width < 2000);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    printf("HC-SR04 Distance Measurement\n");

    while (!terminate) {
        int pulse_width = read_pulse_width();
        if (validate_pulse_width(pulse_width)) {
            printf("Distance: %d us\n", pulse_width);
        } else {
            printf("Invalid reading, retrying...\n");
        }
        gpioDelay(500000); // 0.5 seconds
    }

    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return 0;
}

