#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PINS {4, 17, 18, 22, 23, 24, 25, 27}
#define NUM_PINS 8

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int i;
    int pin_states[NUM_PINS];

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    for (i = 0; i < NUM_PINS; i++) {
        gpioSetMode(GPIO_PINS[i], PI_OUTPUT);
        pin_states[i] = 0; // Initialize all pins to LOW
    }

    printf("GPIO pins and states:\n");
    for (i = 0; i < NUM_PINS; i++) {
        printf("GPIO %d: %d\n", GPIO_PINS[i], pin_states[i]);
    }

    // Main loop
    while (!terminate) {
        for (i = 0; i < NUM_PINS; i++) {
            gpioWrite(GPIO_PINS[i], pin_states[i]);
            pin_states[i] = !pin_states[i]; // Toggle the state
        }
        sleep(0.05);
    }

    // Clean up and exit
    printf("\nCleaning up and exiting...\n");
    for (i = 0; i < NUM_PINS; i++) {
        gpioWrite(GPIO_PINS[i], 0); // Set all pins to LOW before exiting
    }
    gpioTerminate();
    return 0;
}

