        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(GPIO_17, PI_OUTPUT);
    gpioSetMode(GPIO_27, PI_OUTPUT);
    gpioSetMode(GPIO_4, PI_OUTPUT);

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    while (!terminate) {
        // Set GPIO states
        gpioWrite(GPIO_17, 1);
        gpioWrite(GPIO_27, 0);
        gpioWrite(GPIO_4, 0);

        // Report the state
        printf("GPIO 17: %d, GPIO 27: %d, GPIO 4: %d\n", gpioRead(GPIO_17), gpioRead(GPIO_27), gpioRead(GPIO_4));

        // Wait for 0.5 seconds
        gpioDelay(500000); // 0.5 seconds in microseconds
    }

    // Release GPIOs before exiting
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_GPIO 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int result;
    int pwm_value;

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 18 as PWM output
    result = gpioSetMode(PWM_GPIO, PI_OUTPUT);
    if (result != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output: %d\n", PWM_GPIO, result);
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency
    result = gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);
    if (result != 0) {
        fprintf(stderr, "Failed to set PWM frequency: %d\n", result);
        gpioTerminate();
        return 1;
    }

    // Set PWM range
    result = gpioSetPWMrange(PWM_GPIO, PWM_RANGE);
    if (result != 0) {
        fprintf(stderr, "Failed to set PWM range: %d\n", result);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Generate PWM signal (simple on/off)
        pwm_value = (rand() % 20) + 10; // Random value between 10 and 30
        gpioPWM(PWM_GPIO, pwm_value);

        // Report PWM state
        printf("PWM Value: %d\n", pwm_value);

        // Wait for 0.1 seconds
        gpioDelay(100000); // 100 ms
    }

    // Clean up and exit
    gpioPWM(PWM_GPIO, 0); // Stop PWM
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return 0;
}

