#include <pigpio.h>

#define GPIO_17 17
#define GPIO_21 21

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int gpio17_state = 0;
    int gpio21_state = 0;
    int pigpio_init_result;

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    pigpio_init_result = gpioInitialise();
    if (pigpio_init_result < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", pigpio_init_result);
        return 1;
    }

    // Set GPIO 17 as output
    gpioSetMode(GPIO_17, PI_OUTPUT);
    gpio17_state = 0; // Initialize to a safe state

    // Set GPIO 21 as output
    gpioSetMode(GPIO_21, PI_OUTPUT);
    gpio21_state = 0; // Initialize to a safe state

    printf("GPIO control program started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Set GPIO 17 to the current state
        gpioWrite(GPIO_17, gpio17_state);
        gpio17_state = !gpio17_state; // Toggle the state

        // Set GPIO 21 to the current state
        gpioWrite(GPIO_21, gpio21_state);
        gpio21_state = !gpio21_state; // Toggle the state

        // Print the current state of both GPIOs
        printf("GPIO 17: %d, GPIO 21: %d\n", gpio17_state, gpio21_state);

        // Wait for 0.1 seconds
        usleep(100000); // 100 ms
    }

    // Clean up and exit
    gpioTerminate();
    printf("GPIO control program terminated cleanly.\n");
    return 0;
}

