#define DEBOUNCE_DELAY_MS 50

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int gpio_status;
    int gpio_value;
    int valid_count = 0;
    int max_debounce_samples = 5;
    int debounce_samples[max_debounce_samples];
    int debounce_index = 0;
    int i;

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 24 as an output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    printf("GPIO 24 set as output. Monitoring for state changes...\n");

    while (program_running) {
        // Read the current GPIO value
        gpio_status = gpioRead(GPIO_PIN);

        if (gpio_status < 0) {
            fprintf(stderr, "Error reading GPIO %d: %d\n", GPIO_PIN, gpio_status);
            program_running = 0; // Exit loop on error
            break;
        }

        // Debounce the reading
        debounce_samples[debounce_index] = gpio_status;
        debounce_index = (debounce_index + 1) % max_debounce_samples;

        // Check if the readings are consistent
        if (debounce_samples[debounce_index] == gpio_status) {
            valid_count++;
        } else {
            valid_count = 0; // Reset count if readings are inconsistent
        }

        // Check if the readings are valid after a certain number of samples
        if (valid_count >= (max_debounce_samples / 2)) {
            // If the readings are valid, set the GPIO output
            gpioWrite(GPIO_PIN, gpio_status);
            valid_count = 0; // Reset count after setting the output
        }

        // Wait for a short delay
        usleep(DEBOUNCE_DELAY_MS * 1000); // Convert ms to microseconds
    }

    // Release GPIO resources before exiting
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

