static volatile int echo_received = 0;

// Function prototypes
void signal_handler(int signal);
void echo_callback(int gpio, int level, uint32_t tick);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

// Callback function for echo pin changes
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        // Rising edge
        start_time = tick;
        echo_received = 1;
    } else if (level == 0) {
        // Falling edge
        if (echo_received) {
            end_time = tick;
            echo_received = 0;
        }
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set up interrupt on echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Send a 10us pulse to trigger the sensor
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us delay
    gpioWrite(TRIGGER_PIN, 0);

    // Wait for the echo pulse to be received
    while (!echo_received) {
        gpioDelay(1000); // Wait 1 ms
    }

    // Calculate the pulse width
    uint32_t pulse_width = end_time - start_time;

    // Calculate the distance in centimeters (speed of sound: 343 m/s)
    float distance = (pulse_width / 1000000.0) * 34300.0 / 2.0;

    // Print the distance
    printf("Distance: %.2f cm\n", distance);

    // Clean up and exit
    gpioTerminate();
    return 0;
}

