int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[NUM_GPIOS];
    int i;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    for (i = 0; i < NUM_GPIOS; i++) {
        lines[i] = gpiod_chip_get_line(chip, i);
        if (!lines[i]) {
            perror("Error getting GPIO line");
            gpiod_chip_close(chip);
            return 1;
        }
    }

    // Request lines for output
    for (i = 0; i < NUM_GPIOS; i++) {
        struct gpiod_line_request_config config;
        memset(&config, 0, sizeof(config));
        config.consumer = "gpio_control";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

        if (gpiod_line_request(lines[i], &config, 0) != 0) {
            perror("Error requesting GPIO line for output");
            // Cleanup already opened lines
            for (int j = 0; j < i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return 1;
        }
    }

    // Main loop
    while (1) {
        for (i = 0; i < NUM_GPIOS; i++) {
            struct gpiod_line *line = lines[i];
            int value = gpiod_line_get_value(line);
            printf("GPIO %d: %d\n", i, value);
        }
        usleep(100000); // 100ms
    }

    // Cleanup (this part will not be reached in the infinite loop)
    for (i = 0; i < NUM_GPIOS; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 17

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        // Rising edge
        gpioSetTimerFuncEx(ECHO_PIN, 0, 0, NULL); // Disable further callbacks on this pin
    } else if (level == 0) {
        // Falling edge
        uint32_t start = tick;
        gpioSetTimerFuncEx(ECHO_PIN, 0, 0, NULL); // Disable further callbacks on this pin

        // Wait for the rising edge (or timeout)
        while (gpioRead(ECHO_PIN) == 0) {
            if (terminate) return;
            usleep(1000); // Sleep for 1ms to avoid busy-waiting
        }

        uint32_t end = tick;
        double duration = (double)(end - start) / 1000000.0; // Duration in seconds

        if (duration > 0.0 && duration < 0.5) {
            printf("Distance: %.2f cm\n", duration * 30.0); // Convert seconds to cm
        } else {
            printf("Invalid distance reading: %.2f cm\n", duration);
        }
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(2);
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);

    signal(SIGINT, signal_handler);

    gpioSetTimerFuncEx(ECHO_PIN, 50, 0, echo_callback); // Set up timer for echo pin

    while (!terminate) {
        sleep(0.1);
    }

    gpioSetTimerFuncEx(ECHO_PIN, 0, 0, NULL); // Disable timer
    gpioTerminate();
    return 0;
}

