#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define TCS34725_ADDRESS 0x29
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_CONTROL 0x0F
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A

int i2c_fd;

// Function to initialize the TCS34725 sensor
int init_tcs34725() {
    uint8_t buf[2];
    buf[0] = TCS34725_ENABLE;
    buf[1] = 0x03; // Enable power and ALS
    if (write(i2c_fd, buf, 2) != 2) {
        perror("Failed to write to TCS34725_ENABLE");
        return -1;
    }

    buf[0] = TCS34725_ATIME;
    buf[1] = 0xD5; // Integration time (adjust as needed)
    if (write(i2c_fd, buf, 2) != 2) {
        perror("Failed to write to TCS34725_ATIME");
        return -1;
    }

    buf[0] = TCS34725_CONTROL;
    buf[1] = 0x01; // Enable RGBC
    if (write(i2c_fd, buf, 2) != 2) {
        perror("Failed to write to TCS34725_CONTROL");
        return -1;
    }

    return 0;
}

// Function to read color data from the TCS34725 sensor
int read_color_data(uint16_t *r, uint16_t *g, uint16_t *b, uint16_t *c) {
    uint8_t buffer[8];

    // Read all color data registers in one go
    if (read(i2c_fd, buffer, 8) != 8) {
        perror("Failed to read color data");
        return -1;
    }

    *c = (buffer[2] << 8) | buffer[1];
    *r = (buffer[4] << 8) | buffer[3];
    *g = (buffer[6] << 8) | buffer[5];
    *b = (buffer[8] << 8) | buffer[7];

    return 0;
}

int main() {
    uint16_t red, green, blue, clear;

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Initialize the TCS34725 sensor
    if (init_tcs34725() != 0) {
        fprintf(stderr, "TCS34725 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    printf("TCS34725 sensor initialized successfully.\n");

    // Main loop to read and print color data
    while (1) {
        if (read_color_data(&red, &green, &blue, &clear) == 0) {
            printf("R: %5u, G: %5u, B: %5u, C: %5u\n", red, green, blue, clear);
        } else {
            fprintf(stderr, "Failed to read color data.\n");
        }

        usleep(500000); // 0.5 seconds
    }

    // Close I2C device (this will never be reached in the current loop)
    close(i2c_fd);

    return 0;
}

