#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define UART_PORT "/dev/ttyS0" // Or /dev/ttyAMA0
#define BAUD_RATE B115200
#define READ_SIZE 1024
#define MAX_RETRIES 3

int serial_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("\nCtrl+C pressed. Exiting gracefully...\n");
        if (serial_fd != -1) {
            close(serial_fd);
        }
        exit(0);
    }
}

// Function to initialize the UART port
int init_uart(const char *port) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        perror("Error opening UART port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;  // 8N1, no parity
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0; // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read doesn't block
    tty.c_cc[VTIME] = 5; // 0.5 seconds read timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read data from the UART port with retries
int read_uart_data(int fd, char *buffer, int size) {
    int bytes_read = 0;
    int retries = 0;

    while (bytes_read < size && retries < MAX_RETRIES) {
        ssize_t count = read(fd, buffer + bytes_read, size - bytes_read);
        if (count > 0) {
            bytes_read += count;
        } else if (count == -1) {
            perror("Error reading from UART");
            retries++;
            usleep(100000); // Wait 100ms before retrying
        } else {
            // No data available, but we still read to avoid blocking
            bytes_read = count;
        }
    }

    if (bytes_read == 0) {
        fprintf(stderr, "Error: No data received from UART after %d retries.\n", MAX_RETRIES);
        return -1; // Indicate failure
    }

    return bytes_read;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize UART
    serial_fd = init_uart(UART_PORT);
    if (serial_fd == -1) {
        fprintf(stderr, "Failed to initialize UART. Exiting.\n");
        return 1;
    }

    char buffer[READ_SIZE];
    int bytes_read;

    while (1) {
        bytes_read = read_uart_data(serial_fd, buffer, READ_SIZE);
        if (bytes_read > 0) {
            printf("Received: %s\n", buffer);
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from UART. Exiting.\n");
            close(serial_fd);
            return 1;
        }

        usleep(100000); // 0.1 seconds
    }

    return 0;
}

