#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 18
#define ECHO_PIN 23

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        // Rising edge
        gpioSetTimerFuncEx(ECHO_PIN, 0, 0, NULL); // Disable further callbacks on this pin
    } else if (level == 0) {
        // Falling edge
        uint32_t start = tick;
        gpioSetTimerFuncEx(ECHO_PIN, 0, 0, NULL); // Disable further callbacks on this pin
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(2);
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);

    signal(SIGINT, signal_handler);

    gpioSetTimerFuncEx(ECHO_PIN, 50, 0, echo_callback); // Set up timer to disable callback after 50ms

    while (!terminate) {
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(10);
        gpioWrite(TRIGGER_PIN, 0);
        gpioDelay(50);
    }

    gpioSetTimerFuncEx(ECHO_PIN, 0, 0, NULL); // Disable callback

    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define DEBOUNCE_DELAY_MS 50

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int gpio_status;
    int valid_reading = 0;
    int i;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 18 as an output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    printf("GPIO 18 set as output. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read the digital value from GPIO 18
        gpio_status = gpioRead(GPIO_PIN);

        if (gpio_status < 0) {
            fprintf(stderr, "Error reading GPIO %d\n", GPIO_PIN);
            gpioTerminate();
            return 1;
        }

        // Debounce the reading
        gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Convert ms to microseconds

        // Check if the reading is valid (LOW)
        if (gpio_status == 0) {
            valid_reading = 1;
        } else {
            valid_reading = 0;
        }

        // Report the state to standard output
        printf("GPIO %d: %s\n", GPIO_PIN, valid_reading ? "LOW" : "HIGH");

        // Wait for a short period
        gpioDelay(100000); // 100ms
    }

    // Terminate pigpio library before exiting
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

