#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signum) {
    if (signum == SIGINT) {
        program_running = 0;
        fprintf(stderr, "\nSIGINT received, exiting gracefully...\n");
    }
}

// Function to initialize the MPU6050
int init_mpu6050(int fd) {
    // Wake up the MPU6050 (clear sleep mode bit)
    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Error: Could not acquire bus access or talk to slave.");
        return -1;
    }
    if (write(fd, "\0", 1) != 1) {
        perror("Error: Could not write to MPU6050.");
        return -1;
    }
    return 0;
}

// Function to read accelerometer data from the MPU6050
int read_accelerometer(int fd, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z) {
    char buffer[6];

    if (read(fd, buffer, 6) != 6) {
        perror("Error: Could not read accelerometer data.");
        return -1;
    }

    *accel_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *accel_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *accel_z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

int main() {
    int fd;
    int16_t accel_x, accel_y, accel_z;
    struct timespec sleep_time;
    sleep_time.tv_sec = 1;  // 1 second
    sleep_time.tv_nsec = 0; // 0 nanoseconds

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open I2C bus
    if ((fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Error: Could not open I2C bus.");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Error: Could not acquire bus access or talk to slave.");
        close(fd);
        return 1;
    }

    // Initialize the MPU6050
    if (init_mpu6050(fd) < 0) {
        close(fd);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read accelerometer data
        if (read_accelerometer(fd, &accel_x, &accel_y, &accel_z) == 0) {
            // Print the accelerometer readings
            printf("Accelerometer readings: X=%d, Y=%d, Z=%d\n", accel_x, accel_y, accel_z);
        } else {
            fprintf(stderr, "Error reading accelerometer data.\n");
        }

        // Sleep for 1 second
        if (nanosleep(&sleep_time, NULL) != 0) {
            perror("nanosleep");
        }
    }

    // Close the I2C bus
    close(fd);

    return 0;
}

